// correct là câu đã sửa tối thiểu, py/vi là pinyin và nghĩa của câu đúng, type là loại lỗi, explain là giải thích.
// Muốn bỏ một câu sau khi rà soát: xoá dòng có id tương ứng.
window.FIX_ITEMS = [
  {"id":"h2-1-01","std":"hsk2","level":1,"type":"Thiếu/thừa thành phần","wrong":"我的中国朋友是很高兴。","segments":["我的","中国朋友","是很","高兴。"],"bad":2,"correct":"我的中国朋友很高兴。","py":"Wǒ de Zhōngguó péngyou hěn gāoxìng.","vi":"Người bạn Trung Quốc của tôi rất vui.","explain":"Tính từ làm vị ngữ không cần 是, chỉ cần 很 + tính từ. Người Việt hay thêm 是 vì dịch theo chữ \"là\"."},
  {"id":"h2-1-02","std":"hsk2","level":1,"type":"Trật tự từ","wrong":"妈妈买的衣服漂亮很。","segments":["妈妈","买的","衣服","漂亮很。"],"bad":3,"correct":"妈妈买的衣服很漂亮。","py":"Māma mǎi de yīfu hěn piàoliang.","vi":"Quần áo mẹ mua rất đẹp.","explain":"很 là phó từ, phải đứng trước tính từ: 很漂亮. Tiếng Việt nói \"đẹp lắm\" nên người học dễ đặt 很 ra sau."},
  {"id":"h2-1-03","std":"hsk2","level":1,"type":"Trật tự từ","wrong":"我有一个朋友中国。","segments":["我","有","一个","朋友中国。"],"bad":3,"correct":"我有一个中国朋友。","py":"Wǒ yǒu yí ge Zhōngguó péngyou.","vi":"Tôi có một người bạn Trung Quốc.","explain":"Trong tiếng Trung, từ bổ nghĩa đứng trước danh từ: 中国朋友 (bạn Trung Quốc), ngược với trật tự tiếng Việt."},
  {"id":"h2-1-04","std":"hsk2","level":1,"type":"Trật tự từ","wrong":"这是书的我，那是你的。","segments":["这是","书的我，","那是","你的。"],"bad":1,"correct":"这是我的书，那是你的。","py":"Zhè shì wǒ de shū, nà shì nǐ de.","vi":"Đây là sách của tôi, kia là của bạn.","explain":"Sở hữu nói theo thứ tự người sở hữu + 的 + vật: 我的书. Không dịch từng chữ \"sách của tôi\" thành 书的我."},
  {"id":"h2-1-05","std":"hsk2","level":1,"type":"Lượng từ","wrong":"我在北京有三朋友。","segments":["我","在北京","有","三朋友。"],"bad":3,"correct":"我在北京有三个朋友。","py":"Wǒ zài Běijīng yǒu sān ge péngyou.","vi":"Tôi có ba người bạn ở Bắc Kinh.","explain":"Giữa số từ và danh từ phải có lượng từ: 三个朋友. Không nói 三朋友."},
  {"id":"h2-1-06","std":"hsk2","level":1,"type":"Lượng từ","wrong":"我在商店买了三个书。","segments":["我","在商店","买了","三个书。"],"bad":3,"correct":"我在商店买了三本书。","py":"Wǒ zài shāngdiàn mǎi le sān běn shū.","vi":"Tôi đã mua ba quyển sách ở cửa hàng.","explain":"Sách dùng lượng từ 本 (quyển): 三本书. 个 là lượng từ chung nhưng không dùng cho sách."},
  {"id":"h2-1-07","std":"hsk2","level":1,"type":"不/没","wrong":"昨天下午我不去商店。","segments":["昨天下午","我","不去","商店。"],"bad":2,"correct":"昨天下午我没去商店。","py":"Zuótiān xiàwǔ wǒ méi qù shāngdiàn.","vi":"Chiều hôm qua tôi không đi cửa hàng.","explain":"Phủ định việc đã không xảy ra trong quá khứ dùng 没. 不 dùng cho hiện tại, tương lai, thói quen hoặc ý muốn."},
  {"id":"h2-1-08","std":"hsk2","level":1,"type":"不/没","wrong":"我们家不有猫。","segments":["我们","家","不有","猫。"],"bad":2,"correct":"我们家没有猫。","py":"Wǒmen jiā méiyǒu māo.","vi":"Nhà chúng tôi không nuôi mèo.","explain":"Động từ 有 chỉ phủ định bằng 没: 没有. Không bao giờ nói 不有."},
  {"id":"h2-1-09","std":"hsk2","level":1,"type":"Câu hỏi","wrong":"你爸爸的医院在哪里吗？","segments":["你","爸爸的医院","在","哪里吗？"],"bad":3,"correct":"你爸爸的医院在哪里？","py":"Nǐ bàba de yīyuàn zài nǎlǐ?","vi":"Bệnh viện của bố bạn ở đâu?","explain":"Câu đã có từ để hỏi (哪里, 什么, 谁…) thì cuối câu không thêm 吗."},
  {"id":"h2-1-10","std":"hsk2","level":1,"type":"Liên từ","wrong":"我喜欢喝茶，和他喜欢喝水。","segments":["我喜欢","喝茶，","和他","喜欢喝水。"],"bad":2,"correct":"我喜欢喝茶，他喜欢喝水。","py":"Wǒ xǐhuan hē chá, tā xǐhuan hē shuǐ.","vi":"Tôi thích uống trà, anh ấy thích uống nước.","explain":"和 chỉ nối danh từ hoặc đại từ (我和他), không dùng để nối hai vế câu như chữ \"và\" trong tiếng Việt."},
  {"id":"h2-1-11","std":"hsk2","level":1,"type":"的/地/得","wrong":"我家前面有一个很大商店。","segments":["我家前面","有","一个","很大商店。"],"bad":3,"correct":"我家前面有一个很大的商店。","py":"Wǒ jiā qiánmiàn yǒu yí ge hěn dà de shāngdiàn.","vi":"Trước nhà tôi có một cửa hàng rất lớn.","explain":"Cụm \"很 + tính từ\" đứng trước danh từ thì phải có 的: 很大的商店."},
  {"id":"h2-1-12","std":"hsk2","level":1,"type":"Trật tự từ","wrong":"明天我们十点上午去学校。","segments":["明天","我们","十点上午","去学校。"],"bad":2,"correct":"明天我们上午十点去学校。","py":"Míngtiān wǒmen shàngwǔ shí diǎn qù xuéxiào.","vi":"Ngày mai 10 giờ sáng chúng ta đến trường.","explain":"Thời gian trong tiếng Trung đi từ lớn đến nhỏ: 上午十点 (buổi trước, giờ sau), ngược với \"10 giờ sáng\"."},
  {"id":"h2-1-13","std":"hsk2","level":1,"type":"Trật tự từ","wrong":"今天是五日九月，星期三。","segments":["今天","是","五日九月，","星期三。"],"bad":2,"correct":"今天是九月五日，星期三。","py":"Jīntiān shì jiǔ yuè wǔ rì, xīngqīsān.","vi":"Hôm nay là ngày 5 tháng 9, thứ Tư.","explain":"Ngày tháng viết theo thứ tự năm, tháng, ngày: 九月五日. Tiếng Việt nói ngày trước nên dễ đảo."},
  {"id":"h2-1-14","std":"hsk2","level":1,"type":"Trật tự từ","wrong":"我下午看电视在家，你呢？","segments":["我","下午","看电视在家，","你呢？"],"bad":2,"correct":"我下午在家看电视，你呢？","py":"Wǒ xiàwǔ zài jiā kàn diànshì, nǐ ne?","vi":"Chiều nay tôi ở nhà xem tivi, còn bạn?","explain":"Cụm 在 + nơi chốn đứng trước động từ: 在家看电视, không đặt sau như tiếng Việt \"xem tivi ở nhà\"."},
  {"id":"h2-1-15","std":"hsk2","level":1,"type":"Trật tự từ","wrong":"我爸爸是不医生，他是老师。","segments":["我爸爸","是不","医生，","他是老师。"],"bad":1,"correct":"我爸爸不是医生，他是老师。","py":"Wǒ bàba bú shì yīshēng, tā shì lǎoshī.","vi":"Bố tôi không phải bác sĩ, ông ấy là giáo viên.","explain":"不 đứng trước động từ mà nó phủ định: 不是. Nói 是不 là sai."},
  {"id":"h2-1-16","std":"hsk2","level":1,"type":"了/过/着","wrong":"下午我想去了商店买东西。","segments":["下午","我想","去了商店","买东西。"],"bad":2,"correct":"下午我想去商店买东西。","py":"Xiàwǔ wǒ xiǎng qù shāngdiàn mǎi dōngxi.","vi":"Chiều nay tôi muốn đi cửa hàng mua đồ.","explain":"想 nói về việc muốn làm, chưa xảy ra, nên sau động từ không dùng 了 chỉ sự hoàn thành."},
  {"id":"h2-1-17","std":"hsk2","level":1,"type":"Trật tự từ","wrong":"他们是都我的汉语学生。","segments":["他们","是都","我的","汉语学生。"],"bad":1,"correct":"他们都是我的汉语学生。","py":"Tāmen dōu shì wǒ de Hànyǔ xuésheng.","vi":"Họ đều là học sinh tiếng Trung của tôi.","explain":"Phó từ 都 đứng trước động từ: 都是. Không đặt 都 sau 是."},
  {"id":"h2-1-18","std":"hsk2","level":1,"type":"Trật tự từ","wrong":"我喜欢很看中国电影。","segments":["我","喜欢很","看","中国电影。"],"bad":1,"correct":"我很喜欢看中国电影。","py":"Wǒ hěn xǐhuan kàn Zhōngguó diànyǐng.","vi":"Tôi rất thích xem phim Trung Quốc.","explain":"很 bổ nghĩa cho 喜欢 nên phải đứng trước nó: 很喜欢."},
  {"id":"h2-1-19","std":"hsk2","level":1,"type":"Câu hỏi","wrong":"你妈妈现在怎么样吗？","segments":["你","妈妈","现在","怎么样吗？"],"bad":3,"correct":"你妈妈现在怎么样？","py":"Nǐ māma xiànzài zěnmeyàng?","vi":"Mẹ bạn bây giờ thế nào rồi?","explain":"怎么样 đã là từ để hỏi nên cuối câu không thêm 吗."},
  {"id":"h2-1-20","std":"hsk2","level":1,"type":"Kết hợp từ","wrong":"我想给妈妈叫电话。","segments":["我","想","给妈妈","叫电话。"],"bad":3,"correct":"我想给妈妈打电话。","py":"Wǒ xiǎng gěi māma dǎ diànhuà.","vi":"Tôi muốn gọi điện cho mẹ.","explain":"\"Gọi điện\" trong tiếng Trung là 打电话. 叫 là gọi tên, kêu ai đó, không đi với 电话."},
  {"id":"h2-2-01","std":"hsk2","level":2,"type":"二/两","wrong":"我家有二个孩子。","segments":["我家","有","二个","孩子。"],"bad":2,"correct":"我家有两个孩子。","py":"Wǒ jiā yǒu liǎng ge háizi.","vi":"Nhà tôi có hai đứa con.","explain":"Trước lượng từ dùng 两, không dùng 二: 两个孩子. 二 dùng khi đếm số hoặc trong số nhiều chữ số (十二, 第二)."},
  {"id":"h2-2-02","std":"hsk2","level":2,"type":"Câu so sánh","wrong":"我哥哥比我很高。","segments":["我哥哥","比","我","很高。"],"bad":3,"correct":"我哥哥比我高。","py":"Wǒ gēge bǐ wǒ gāo.","vi":"Anh trai tôi cao hơn tôi.","explain":"Câu so sánh với 比 không dùng 很, 非常 trước tính từ. Muốn nói \"cao hơn nhiều\" thì dùng 高多了 hoặc 高得多."},
  {"id":"h2-2-03","std":"hsk2","level":2,"type":"Bổ ngữ","wrong":"我弟弟跑非常快，他每天都跑步。","segments":["我弟弟","跑非常快，","他每天","都跑步。"],"bad":1,"correct":"我弟弟跑得非常快，他每天都跑步。","py":"Wǒ dìdi pǎo de fēicháng kuài, tā měi tiān dōu pǎobù.","vi":"Em trai tôi chạy rất nhanh, ngày nào nó cũng chạy bộ.","explain":"Muốn nhận xét động tác diễn ra thế nào phải dùng bổ ngữ trạng thái: động từ + 得 + tính từ (跑得非常快)."},
  {"id":"h2-2-04","std":"hsk2","level":2,"type":"了/过/着","wrong":"你来的时候，他正在看了电视。","segments":["你来的时候，","他","正在看了","电视。"],"bad":2,"correct":"你来的时候，他正在看电视。","py":"Nǐ lái de shíhou, tā zhèngzài kàn diànshì.","vi":"Lúc bạn đến, anh ấy đang xem tivi.","explain":"正在 diễn tả hành động đang diễn ra, không dùng chung với 了 chỉ sự hoàn thành."},
  {"id":"h2-2-06","std":"hsk2","level":2,"type":"了/过/着","wrong":"昨天我在机场等他了两个小时。","segments":["昨天","我在机场","等他了","两个小时。"],"bad":2,"correct":"昨天我在机场等了他两个小时。","py":"Zuótiān wǒ zài jīchǎng děng le tā liǎng ge xiǎoshí.","vi":"Hôm qua tôi đợi anh ấy ở sân bay hai tiếng.","explain":"了 đứng ngay sau động từ, trước tân ngữ và khoảng thời gian: 等了他两个小时."},
  {"id":"h2-2-07","std":"hsk2","level":2,"type":"Lượng từ","wrong":"昨天我买了两张衣服。","segments":["昨天","我","买了","两张衣服。"],"bad":3,"correct":"昨天我买了两件衣服。","py":"Zuótiān wǒ mǎi le liǎng jiàn yīfu.","vi":"Hôm qua tôi mua hai cái áo.","explain":"Quần áo dùng lượng từ 件. 张 dùng cho vật mỏng, phẳng như giấy, vé, bàn."},
  {"id":"h2-2-08","std":"hsk2","level":2,"type":"了/过/着","wrong":"昨天下雨，我没去了学校。","segments":["昨天下雨，","我","没去了","学校。"],"bad":2,"correct":"昨天下雨，我没去学校。","py":"Zuótiān xiàyǔ, wǒ méi qù xuéxiào.","vi":"Hôm qua trời mưa, tôi không đi học.","explain":"Câu phủ định với 没 không dùng 了 sau động từ: 没去, không nói 没去了."},
  {"id":"h2-2-09","std":"hsk2","level":2,"type":"Bổ ngữ","wrong":"我吃饭完了，你吃了吗？","segments":["我","吃饭完了，","你","吃了吗？"],"bad":1,"correct":"我吃完饭了，你吃了吗？","py":"Wǒ chī wán fàn le, nǐ chī le ma?","vi":"Tôi ăn cơm xong rồi, bạn ăn chưa?","explain":"Bổ ngữ kết quả 完 đứng ngay sau động từ, trước tân ngữ: 吃完饭."},
  {"id":"h2-2-10","std":"hsk2","level":2,"type":"Giới từ","wrong":"我家从学校很远，我坐公共汽车去。","segments":["我家","从学校","很远，","我坐公共汽车去。"],"bad":1,"correct":"我家离学校很远，我坐公共汽车去。","py":"Wǒ jiā lí xuéxiào hěn yuǎn, wǒ zuò gōnggòng qìchē qù.","vi":"Nhà tôi cách trường rất xa, tôi đi xe buýt.","explain":"Nói khoảng cách giữa hai nơi dùng A 离 B 远/近. 从 chỉ điểm xuất phát, thường đi với 到 hoặc động từ di chuyển."},
  {"id":"h2-2-11","std":"hsk2","level":2,"type":"Liên từ","wrong":"因为下雨了，但是我们没去跑步。","segments":["因为","下雨了，","但是我们","没去跑步。"],"bad":2,"correct":"因为下雨了，所以我们没去跑步。","py":"Yīnwèi xiàyǔ le, suǒyǐ wǒmen méi qù pǎobù.","vi":"Vì trời mưa nên chúng tôi không đi chạy bộ.","explain":"因为 (vì) đi đôi với 所以 (nên). 但是 (nhưng) chỉ dùng khi hai vế trái ý nhau."},
  {"id":"h2-2-12","std":"hsk2","level":2,"type":"Trật tự từ","wrong":"明天我一起和他去机场。","segments":["明天","我","一起和他","去机场。"],"bad":2,"correct":"明天我和他一起去机场。","py":"Míngtiān wǒ hé tā yìqǐ qù jīchǎng.","vi":"Ngày mai tôi cùng anh ấy ra sân bay.","explain":"Cấu trúc đúng là 和 + người + 一起 + động từ: 一起 đứng sau cụm 和他, ngay trước động từ."},
  {"id":"h2-2-13","std":"hsk2","level":2,"type":"Bổ ngữ","wrong":"我的同学打篮球得很好。","segments":["我的","同学","打篮球得","很好。"],"bad":2,"correct":"我的同学打篮球打得很好。","py":"Wǒ de tóngxué dǎ lánqiú dǎ de hěn hǎo.","vi":"Bạn cùng lớp của tôi chơi bóng rổ rất giỏi.","explain":"Động từ có tân ngữ mà muốn thêm bổ ngữ với 得 thì phải lặp lại động từ: 打篮球打得很好 (hoặc 篮球打得很好)."},
  {"id":"h2-2-15","std":"hsk2","level":2,"type":"Thiếu/thừa thành phần","wrong":"上课的时候，我给老师问一个问题。","segments":["上课的时候，","我","给老师问","一个问题。"],"bad":2,"correct":"上课的时候，我问老师一个问题。","py":"Shàngkè de shíhou, wǒ wèn lǎoshī yí ge wèntí.","vi":"Trong giờ học, tôi hỏi thầy một câu.","explain":"问 nhận trực tiếp người được hỏi rồi đến điều cần hỏi: 问老师一个问题, không cần 给."},
  {"id":"h2-2-16","std":"hsk2","level":2,"type":"的/地/得","wrong":"我妹妹游泳游的很快。","segments":["我妹妹","游泳","游的","很快。"],"bad":2,"correct":"我妹妹游泳游得很快。","py":"Wǒ mèimei yóuyǒng yóu de hěn kuài.","vi":"Em gái tôi bơi rất nhanh.","explain":"Nối động từ với bổ ngữ chỉ mức độ, trạng thái phải dùng 得 (游得很快). 的 dùng trước danh từ."},
  {"id":"h2-2-17","std":"hsk2","level":2,"type":"了/过/着","wrong":"我去北京过，那里非常漂亮。","segments":["我","去北京过，","那里","非常漂亮。"],"bad":1,"correct":"我去过北京，那里非常漂亮。","py":"Wǒ qùguo Běijīng, nàli fēicháng piàoliang.","vi":"Tôi từng đến Bắc Kinh, ở đó rất đẹp.","explain":"过 (từng) đứng ngay sau động từ, trước tân ngữ: 去过北京."},
  {"id":"h2-2-18","std":"hsk2","level":2,"type":"Lượng từ","wrong":"在我们学校，每学生都有汉语名字。","segments":["在我们学校，","每学生","都有","汉语名字。"],"bad":1,"correct":"在我们学校，每个学生都有汉语名字。","py":"Zài wǒmen xuéxiào, měi ge xuésheng dōu yǒu Hànyǔ míngzi.","vi":"Ở trường chúng tôi, học sinh nào cũng có tên tiếng Trung.","explain":"Sau 每 phải có lượng từ trước danh từ: 每个学生. Chỉ một số danh từ như 天, 年 mới đứng ngay sau 每."},
  {"id":"h2-2-19","std":"hsk2","level":2,"type":"Dùng sai từ","wrong":"我和他是好朋友，我们知道三年了。","segments":["我和他","是好朋友，","我们","知道三年了。"],"bad":3,"correct":"我和他是好朋友，我们认识三年了。","py":"Wǒ hé tā shì hǎo péngyou, wǒmen rènshi sān nián le.","vi":"Tôi và cậu ấy là bạn thân, chúng tôi quen nhau ba năm rồi.","explain":"认识 là quen biết một người; 知道 là biết một thông tin. \"Quen nhau ba năm\" phải dùng 认识."},
  {"id":"h2-2-20","std":"hsk2","level":2,"type":"Thiếu/thừa thành phần","wrong":"我来北京时候，天气非常冷。","segments":["我","来北京时候，","天气","非常冷。"],"bad":1,"correct":"我来北京的时候，天气非常冷。","py":"Wǒ lái Běijīng de shíhou, tiānqì fēicháng lěng.","vi":"Lúc tôi đến Bắc Kinh, trời rất lạnh.","explain":"\"Khi…\" là cụm …的时候; phía trước là cụm động từ thì không được bỏ 的: 来北京的时候."},
  {"id":"h2-3-01","std":"hsk2","level":3,"type":"Câu so sánh","wrong":"我弟弟今年十二岁，他比我不高。","segments":["我弟弟","今年十二岁，","他","比我不高。"],"bad":3,"correct":"我弟弟今年十二岁，他没有我高。","py":"Wǒ dìdi jīnnián shí'èr suì, tā méiyǒu wǒ gāo.","vi":"Em trai tôi năm nay 12 tuổi, nó không cao bằng tôi.","explain":"Phủ định của câu so sánh là A 没有 B + tính từ (A không … bằng B). Không đặt 不 ngay trước tính từ sau 比."},
  {"id":"h2-3-02","std":"hsk2","level":3,"type":"Câu so sánh","wrong":"这件衣服跟那件一样很漂亮，你买哪件？","segments":["这件衣服","跟那件","一样很漂亮，","你买哪件？"],"bad":2,"correct":"这件衣服跟那件一样漂亮，你买哪件？","py":"Zhè jiàn yīfu gēn nà jiàn yíyàng piàoliang, nǐ mǎi nǎ jiàn?","vi":"Cái áo này đẹp như cái kia, bạn mua cái nào?","explain":"Trong câu A 跟 B 一样 + tính từ, tính từ đứng ngay sau 一样, không thêm 很."},
  {"id":"h2-3-03","std":"hsk2","level":3,"type":"Câu chữ 把/被","wrong":"我已经把那本书看。","segments":["我","已经","把那本书","看。"],"bad":3,"correct":"我已经把那本书看完了。","py":"Wǒ yǐjīng bǎ nà běn shū kàn wán le.","vi":"Tôi đã đọc xong quyển sách đó.","explain":"Động từ trong câu chữ 把 không đứng trơ một mình, phải có thành phần khác theo sau như bổ ngữ hoặc 了: 看完了."},
  {"id":"h2-3-04","std":"hsk2","level":3,"type":"Câu chữ 把/被","wrong":"我的自行车被我哥哥骑。","segments":["我的","自行车","被我哥哥","骑。"],"bad":3,"correct":"我的自行车被我哥哥骑走了。","py":"Wǒ de zìxíngchē bèi wǒ gēge qí zǒu le.","vi":"Xe đạp của tôi bị anh trai tôi đạp đi mất rồi.","explain":"Câu bị động với 被 cũng cần thành phần khác sau động từ để nói kết quả: 骑走了."},
  {"id":"h2-3-05","std":"hsk2","level":3,"type":"Câu chữ 把/被","wrong":"老师，我把作业没做完。","segments":["老师，","我","把作业没","做完。"],"bad":2,"correct":"老师，我没把作业做完。","py":"Lǎoshī, wǒ méi bǎ zuòyè zuò wán.","vi":"Thưa thầy, em chưa làm xong bài tập.","explain":"Trong câu chữ 把, từ phủ định 没/不 đặt trước 把, không đặt trước động từ: 没把作业做完."},
  {"id":"h2-3-06","std":"hsk2","level":3,"type":"Thiếu/thừa thành phần","wrong":"十二月了，天气越来越很冷，多穿点儿衣服吧。","segments":["十二月了，","天气","越来越很冷，","多穿点儿衣服吧。"],"bad":2,"correct":"十二月了，天气越来越冷，多穿点儿衣服吧。","py":"Shí'èr yuè le, tiānqì yuèláiyuè lěng, duō chuān diǎnr yīfu ba.","vi":"Tháng mười hai rồi, trời càng ngày càng lạnh, mặc thêm áo vào nhé.","explain":"越来越 đã chỉ mức độ tăng dần nên không dùng thêm 很, 非常 trước tính từ."},
  {"id":"h2-3-07","std":"hsk2","level":3,"type":"Liên từ","wrong":"虽然外面下雨了，所以他还是去上班了。","segments":["虽然","外面下雨了，","所以他","还是去上班了。"],"bad":2,"correct":"虽然外面下雨了，但是他还是去上班了。","py":"Suīrán wàimiàn xiàyǔ le, dànshì tā háishi qù shàngbān le.","vi":"Tuy bên ngoài trời mưa nhưng anh ấy vẫn đi làm.","explain":"虽然 (tuy) đi với 但是/可是 (nhưng) để nối hai vế trái ý; 所以 đi với 因为."},
  {"id":"h2-3-08","std":"hsk2","level":3,"type":"Liên từ","wrong":"如果你明天有时间，所以来我家玩吧。","segments":["如果","你明天有时间，","所以","来我家玩吧。"],"bad":2,"correct":"如果你明天有时间，就来我家玩吧。","py":"Rúguǒ nǐ míngtiān yǒu shíjiān, jiù lái wǒ jiā wán ba.","vi":"Nếu mai bạn rảnh thì đến nhà tôi chơi nhé.","explain":"如果 (nếu) đi với 就 ở vế sau. 所以 chỉ kết quả của một nguyên nhân, không dùng trong câu điều kiện."},
  {"id":"h2-3-09","std":"hsk2","level":3,"type":"Câu 是…的","wrong":"我是去年来了中国的，现在会说一点儿汉语。","segments":["我","是去年","来了中国的，","现在会说一点儿汉语。"],"bad":2,"correct":"我是去年来中国的，现在会说一点儿汉语。","py":"Wǒ shì qùnián lái Zhōngguó de, xiànzài huì shuō yìdiǎnr Hànyǔ.","vi":"Tôi sang Trung Quốc từ năm ngoái, giờ đã nói được chút tiếng Trung.","explain":"Câu 是…的 nhấn mạnh thời gian, nơi chốn, cách thức của việc đã xảy ra; động từ trong câu này không mang 了."},
  {"id":"h2-3-10","std":"hsk2","level":3,"type":"Kết hợp từ","wrong":"除了汉语以外，他都会说英语。","segments":["除了汉语以外，","他","都会说","英语。"],"bad":2,"correct":"除了汉语以外，他还会说英语。","py":"Chúle Hànyǔ yǐwài, tā hái huì shuō Yīngyǔ.","vi":"Ngoài tiếng Trung, anh ấy còn biết nói tiếng Anh.","explain":"除了…以外 đi với 还/也 khi nghĩa là \"ngoài … ra còn\"; đi với 都 khi nghĩa là \"trừ … ra, tất cả đều\"."},
  {"id":"h2-3-12","std":"hsk2","level":3,"type":"Lượng từ","wrong":"昨天我在商店买了一条新鞋。","segments":["昨天","我在商店","买了","一条新鞋。"],"bad":3,"correct":"昨天我在商店买了一双新鞋。","py":"Zuótiān wǒ zài shāngdiàn mǎi le yì shuāng xīn xié.","vi":"Hôm qua tôi mua một đôi giày mới ở cửa hàng.","explain":"Giày, tất, đũa… đi theo đôi nên dùng 双. 条 dùng cho vật dài như quần, cá, con đường."},
  {"id":"h2-3-13","std":"hsk2","level":3,"type":"Lượng từ","wrong":"我想去商店买一件裤子。","segments":["我","想去商店","买","一件裤子。"],"bad":3,"correct":"我想去商店买一条裤子。","py":"Wǒ xiǎng qù shāngdiàn mǎi yì tiáo kùzi.","vi":"Tôi muốn đi cửa hàng mua một cái quần.","explain":"Quần dùng lượng từ 条 (vật dài). 件 dùng cho áo (衬衫, 外套) và cho danh từ chung 衣服, không dùng cho quần."},
  {"id":"h2-3-14","std":"hsk2","level":3,"type":"Bổ ngữ","wrong":"老师说的话我听了懂。","segments":["老师","说的话","我","听了懂。"],"bad":3,"correct":"老师说的话我听懂了。","py":"Lǎoshī shuō de huà wǒ tīng dǒng le.","vi":"Tôi nghe hiểu lời thầy nói rồi.","explain":"Bổ ngữ kết quả 懂 đứng sát sau động từ, 了 đặt sau bổ ngữ: 听懂了."},
  {"id":"h2-3-15","std":"hsk2","level":3,"type":"Bổ ngữ","wrong":"下课以后，他回去家了，不在学校。","segments":["下课以后，","他","回去家了，","不在学校。"],"bad":2,"correct":"下课以后，他回家去了，不在学校。","py":"Xiàkè yǐhòu, tā huí jiā qù le, bú zài xuéxiào.","vi":"Tan học xong cậu ấy về nhà rồi, không còn ở trường.","explain":"Bổ ngữ xu hướng 来/去 đi với tân ngữ chỉ nơi chốn thì tân ngữ phải đứng trước 来/去: 回家去."},
  {"id":"h2-3-16","std":"hsk2","level":3,"type":"了/过/着","wrong":"你看，桌子上放一本书着，是谁的？","segments":["你看，","桌子上","放一本书着，","是谁的？"],"bad":2,"correct":"你看，桌子上放着一本书，是谁的？","py":"Nǐ kàn, zhuōzi shang fàngzhe yì běn shū, shì shéi de?","vi":"Bạn xem, trên bàn có một quyển sách, của ai vậy?","explain":"着 đứng ngay sau động từ, trước tân ngữ: 放着一本书. Đây là mẫu câu \"nơi chốn + động từ + 着 + vật\"."},
  {"id":"h2-3-17","std":"hsk2","level":3,"type":"的/地/得","wrong":"看到妈妈，孩子高兴的笑了。","segments":["看到妈妈，","孩子","高兴的","笑了。"],"bad":2,"correct":"看到妈妈，孩子高兴地笑了。","py":"Kàn dào māma, háizi gāoxìng de xiào le.","vi":"Thấy mẹ, đứa bé cười rất vui.","explain":"Từ bổ nghĩa đứng trước động từ (trạng ngữ) dùng 地: 高兴地笑. 的 dùng trước danh từ."},
  {"id":"h2-3-18","std":"hsk2","level":3,"type":"Liên từ","wrong":"为了下大雨，我们没去公园。","segments":["为了","下大雨，","我们","没去公园。"],"bad":0,"correct":"因为下大雨，我们没去公园。","py":"Yīnwèi xià dà yǔ, wǒmen méi qù gōngyuán.","vi":"Vì mưa to nên chúng tôi không đi công viên.","explain":"为了 nêu mục đích (để); nêu nguyên nhân phải dùng 因为."},
  {"id":"h2-3-19","std":"hsk2","level":3,"type":"Động từ ly hợp","wrong":"这些书太多了，你可以帮忙我吗？","segments":["这些书","太多了，","你可以","帮忙我吗？"],"bad":3,"correct":"这些书太多了，你可以帮我吗？","py":"Zhèxiē shū tài duō le, nǐ kěyǐ bāng wǒ ma?","vi":"Chỗ sách này nhiều quá, bạn giúp tôi được không?","explain":"帮忙 là động từ ly hợp (帮 + 忙), không mang tân ngữ phía sau. Nói 帮我 hoặc 帮我一个忙."},
  {"id":"h2-3-20","std":"hsk2","level":3,"type":"Động từ ly hợp","wrong":"去年我姐姐结婚了一个医生，现在他们住在北京。","segments":["去年","我姐姐","结婚了一个医生，","现在他们住在北京。"],"bad":2,"correct":"去年我姐姐跟一个医生结婚了，现在他们住在北京。","py":"Qùnián wǒ jiějie gēn yí ge yīshēng jiéhūn le, xiànzài tāmen zhù zài Běijīng.","vi":"Năm ngoái chị tôi kết hôn với một bác sĩ, giờ họ sống ở Bắc Kinh.","explain":"结婚 không mang tân ngữ; người kết hôn cùng đi với 跟/和 đặt trước: 跟一个医生结婚."},
  {"id":"h2-4-01","std":"hsk2","level":4,"type":"Liên từ","wrong":"不管明天下雨，我们都要去。","segments":["不管","明天下雨，","我们","都要去。"],"bad":1,"correct":"不管明天下不下雨，我们都要去。","py":"Bùguǎn míngtiān xià bu xià yǔ, wǒmen dōu yào qù.","vi":"Dù mai trời có mưa hay không, chúng tôi cũng sẽ đi.","explain":"Sau 不管 phải là cụm có lựa chọn hoặc từ để hỏi (下不下雨, 怎么样, 谁…). Nếu chỉ nêu một điều kiện cụ thể thì dùng 即使…也…."},
  {"id":"h2-4-02","std":"hsk2","level":4,"type":"Thiếu/thừa thành phần","wrong":"这个孩子才三岁，他连名字不会写。","segments":["这个孩子","才三岁，","他","连名字不会写。"],"bad":3,"correct":"这个孩子才三岁，他连名字都不会写。","py":"Zhège háizi cái sān suì, tā lián míngzi dōu bú huì xiě.","vi":"Đứa bé này mới ba tuổi, đến tên mình nó còn chưa biết viết.","explain":"Cấu trúc 连…都/也… (ngay cả … cũng) phải có 都 hoặc 也 trước động từ: 连名字都不会写."},
  {"id":"h2-4-04","std":"hsk2","level":4,"type":"Liên từ","wrong":"既然你不舒服，所以早点儿回家休息吧。","segments":["既然","你不舒服，","所以","早点儿回家休息吧。"],"bad":2,"correct":"既然你不舒服，就早点儿回家休息吧。","py":"Jìrán nǐ bù shūfu, jiù zǎo diǎnr huí jiā xiūxi ba.","vi":"Bạn đã thấy không khỏe thì về nhà nghỉ sớm đi.","explain":"既然 (đã … thì) đi với 就 ở vế sau, dùng khi khuyên hoặc rút ra kết luận. Không dùng 所以 với 既然."},
  {"id":"h2-4-05","std":"hsk2","level":4,"type":"Bổ ngữ","wrong":"刚才还是晴天，现在下起来雨了。","segments":["刚才","还是晴天，","现在","下起来雨了。"],"bad":3,"correct":"刚才还是晴天，现在下起雨来了。","py":"Gāngcái hái shì qíngtiān, xiànzài xià qǐ yǔ lai le.","vi":"Lúc nãy trời còn nắng, giờ đã đổ mưa rồi.","explain":"Khi 起来 có tân ngữ, tân ngữ chen vào giữa 起 và 来: 下起雨来."},
  {"id":"h2-4-06","std":"hsk2","level":4,"type":"Bổ ngữ","wrong":"今天早上起晚了，我不来及吃早饭。","segments":["今天早上","起晚了，","我","不来及吃早饭。"],"bad":3,"correct":"今天早上起晚了，我来不及吃早饭。","py":"Jīntiān zǎoshang qǐ wǎn le, wǒ láibují chī zǎofàn.","vi":"Sáng nay dậy muộn, tôi không kịp ăn sáng.","explain":"\"Không kịp\" là 来不及, 不 chen giữa 来 và 及. Dạng khẳng định là 来得及."},
  {"id":"h2-4-07","std":"hsk2","level":4,"type":"了/过/着","wrong":"我从来没喝了酒。","segments":["我","从来","没喝了","酒。"],"bad":2,"correct":"我从来没喝过酒。","py":"Wǒ cónglái méi hēguo jiǔ.","vi":"Tôi chưa bao giờ uống rượu.","explain":"从来没 (chưa từng) đi với 过 để nói về trải nghiệm: 从来没喝过. 了 không dùng sau 没 + động từ."},
  {"id":"h2-4-08","std":"hsk2","level":4,"type":"Kết hợp từ","wrong":"来中国一年以后，我的汉语水平增加了很多。","segments":["来中国","一年以后，","我的汉语水平","增加了很多。"],"bad":3,"correct":"来中国一年以后，我的汉语水平提高了很多。","py":"Lái Zhōngguó yì nián yǐhòu, wǒ de Hànyǔ shuǐpíng tígāo le hěn duō.","vi":"Sau một năm ở Trung Quốc, trình độ tiếng Trung của tôi tiến bộ nhiều.","explain":"水平 (trình độ) đi với 提高; 增加 dùng cho số lượng (người, tiền, lần)."},
  {"id":"h2-4-09","std":"hsk2","level":4,"type":"Động từ ly hợp","wrong":"我明天下午在咖啡馆见面他。","segments":["我","明天下午","在咖啡馆","见面他。"],"bad":3,"correct":"我明天下午在咖啡馆跟他见面。","py":"Wǒ míngtiān xiàwǔ zài kāfēiguǎn gēn tā jiànmiàn.","vi":"Chiều mai tôi gặp anh ấy ở quán cà phê.","explain":"见面 là động từ ly hợp, không mang tân ngữ phía sau; người gặp đi với 跟/和: 跟他见面."},
  {"id":"h2-4-10","std":"hsk2","level":4,"type":"Động từ ly hợp","wrong":"昨天晚上我睡觉了八个小时。","segments":["昨天晚上","我","睡觉了","八个小时。"],"bad":2,"correct":"昨天晚上我睡了八个小时。","py":"Zuótiān wǎnshang wǒ shuì le bā ge xiǎoshí.","vi":"Tối qua tôi ngủ tám tiếng.","explain":"睡觉 là động từ ly hợp; khoảng thời gian đặt sau 睡: 睡了八个小时 (hoặc 睡了八个小时的觉)."},
  {"id":"h2-4-11","std":"hsk2","level":4,"type":"Động từ ly hợp","wrong":"我哥哥去年毕业大学，现在在银行工作。","segments":["我哥哥","去年","毕业大学，","现在在银行工作。"],"bad":2,"correct":"我哥哥去年大学毕业，现在在银行工作。","py":"Wǒ gēge qùnián dàxué bìyè, xiànzài zài yínháng gōngzuò.","vi":"Anh trai tôi tốt nghiệp đại học năm ngoái, giờ làm ở ngân hàng.","explain":"毕业 không mang tân ngữ trực tiếp. Nói 大学毕业 hoặc 从大学毕业."},
  {"id":"h2-4-12","std":"hsk2","level":4,"type":"Thiếu/thừa thành phần","wrong":"小王是我最好的一个朋友之一。","segments":["小王","是","我最好的一个","朋友之一。"],"bad":2,"correct":"小王是我最好的朋友之一。","py":"Xiǎo Wáng shì wǒ zuì hǎo de péngyou zhīyī.","vi":"Tiểu Vương là một trong những người bạn thân nhất của tôi.","explain":"之一 đã có nghĩa \"một trong số\", nên không thêm 一个 phía trước nữa."},
  {"id":"h2-4-13","std":"hsk2","level":4,"type":"Thiếu/thừa thành phần","wrong":"雨越下越很大，我们回去吧。","segments":["雨","越下","越很大，","我们回去吧。"],"bad":2,"correct":"雨越下越大，我们回去吧。","py":"Yǔ yuè xià yuè dà, wǒmen huíqu ba.","vi":"Mưa càng lúc càng to, chúng ta về thôi.","explain":"Trong cấu trúc 越…越…, tính từ đứng ngay sau 越, không thêm 很."},
  {"id":"h2-4-14","std":"hsk2","level":4,"type":"Câu chữ 把/被","wrong":"还好，我的钱包被别人没拿走。","segments":["还好，","我的钱包","被别人没","拿走。"],"bad":2,"correct":"还好，我的钱包没被别人拿走。","py":"Hái hǎo, wǒ de qiánbāo méi bèi biérén ná zǒu.","vi":"May quá, ví của tôi không bị người khác lấy mất.","explain":"Trong câu bị động, 没/不 đặt trước 被: 没被别人拿走."},
  {"id":"h2-4-15","std":"hsk2","level":4,"type":"Câu chữ 把/被","wrong":"你别说了，我已经把这件事知道了，谢谢。","segments":["你别说了，","我已经","把这件事知道了，","谢谢。"],"bad":2,"correct":"你别说了，我已经知道这件事了，谢谢。","py":"Nǐ bié shuō le, wǒ yǐjīng zhīdào zhè jiàn shì le, xièxie.","vi":"Bạn đừng nói nữa, tôi biết chuyện này rồi, cảm ơn.","explain":"Câu chữ 把 cần động từ tác động làm thay đổi đối tượng. Các động từ nhận thức như 知道, 认识, 喜欢 không dùng với 把."},
  {"id":"h2-4-16","std":"hsk2","level":4,"type":"Câu hỏi","wrong":"我们都在等你，你到底去不去吗？","segments":["我们","都在等你，","你","到底去不去吗？"],"bad":3,"correct":"我们都在等你，你到底去不去？","py":"Wǒmen dōu zài děng nǐ, nǐ dàodǐ qù bu qù?","vi":"Mọi người đều đang đợi bạn, rốt cuộc bạn có đi không?","explain":"到底 dùng trong câu hỏi có từ để hỏi hoặc dạng khẳng định phủ định (去不去), nên cuối câu không thêm 吗."},
  {"id":"h2-4-17","std":"hsk2","level":4,"type":"Dùng sai từ","wrong":"刚来中国的时候，我不会说汉语，以后慢慢学会了。","segments":["刚来中国的时候，","我不会说汉语，","以后","慢慢学会了。"],"bad":2,"correct":"刚来中国的时候，我不会说汉语，后来慢慢学会了。","py":"Gāng lái Zhōngguó de shíhou, wǒ bú huì shuō Hànyǔ, hòulái mànmàn xué huì le.","vi":"Hồi mới sang Trung Quốc, tôi không biết nói tiếng Trung, sau đó dần dần học được.","explain":"Kể việc xảy ra sau một mốc trong quá khứ dùng 后来. 以后 thường chỉ tương lai hoặc đứng sau một cụm từ (…以后)."},
  {"id":"h2-4-18","std":"hsk2","level":4,"type":"Kết hợp từ","wrong":"我对中国文化很兴趣，想去中国留学。","segments":["我","对中国文化","很兴趣，","想去中国留学。"],"bad":2,"correct":"我对中国文化很感兴趣，想去中国留学。","py":"Wǒ duì Zhōngguó wénhuà hěn gǎn xìngqù, xiǎng qù Zhōngguó liúxué.","vi":"Tôi rất hứng thú với văn hóa Trung Quốc, muốn sang Trung Quốc du học.","explain":"兴趣 là danh từ nên không đi thẳng với 很. Phải nói 很感兴趣 hoặc 很有兴趣."},
  {"id":"h2-4-19","std":"hsk2","level":4,"type":"Dùng sai từ","wrong":"今天医生不在，我明天又来吧。","segments":["今天","医生不在，","我明天","又来吧。"],"bad":3,"correct":"今天医生不在，我明天再来吧。","py":"Jīntiān yīshēng bú zài, wǒ míngtiān zài lái ba.","vi":"Hôm nay bác sĩ không có ở đây, mai tôi quay lại vậy.","explain":"Lặp lại hành động trong tương lai dùng 再; 又 dùng cho việc đã lặp lại trong quá khứ."},
  {"id":"h2-4-20","std":"hsk2","level":4,"type":"Dùng sai từ","wrong":"今天天气一点儿冷，多穿件衣服吧。","segments":["今天","天气","一点儿冷，","多穿件衣服吧。"],"bad":2,"correct":"今天天气有点儿冷，多穿件衣服吧。","py":"Jīntiān tiānqì yǒudiǎnr lěng, duō chuān jiàn yīfu ba.","vi":"Hôm nay trời hơi lạnh, mặc thêm cái áo vào nhé.","explain":"\"Hơi + tính từ\" là 有点儿 + tính từ, thường mang ý không như mong muốn. 一点儿 đứng sau tính từ khi so sánh (冷一点儿)."},
  {"id":"h2-5-01","std":"hsk2","level":5,"type":"Liên từ","wrong":"我之所以学汉语，所以我喜欢中国文化。","segments":["我","之所以学汉语，","所以","我喜欢中国文化。"],"bad":2,"correct":"我之所以学汉语，是因为我喜欢中国文化。","py":"Wǒ zhīsuǒyǐ xué Hànyǔ, shì yīnwèi wǒ xǐhuan Zhōngguó wénhuà.","vi":"Sở dĩ tôi học tiếng Trung là vì tôi thích văn hóa Trung Quốc.","explain":"之所以 (sở dĩ) nêu kết quả trước, vế sau phải dùng 是因为 để nêu nguyên nhân."},
  {"id":"h2-5-03","std":"hsk2","level":5,"type":"Thiếu/thừa thành phần","wrong":"路上太堵了，我宁可走路去，也坐出租车。","segments":["路上太堵了，","我","宁可走路去，","也坐出租车。"],"bad":3,"correct":"路上太堵了，我宁可走路去，也不坐出租车。","py":"Lùshang tài dǔ le, wǒ nìngkě zǒulù qù, yě bú zuò chūzūchē.","vi":"Đường tắc quá, tôi thà đi bộ chứ không đi taxi.","explain":"宁可 A, 也不 B nghĩa là \"thà A chứ không B\". Thiếu 不 thì câu thành nghĩa ngược lại."},
  {"id":"h2-5-04","std":"hsk2","level":5,"type":"Động từ ly hợp","wrong":"今天早上在电梯里，邻居打招呼我。","segments":["今天早上","在电梯里，","邻居","打招呼我。"],"bad":3,"correct":"今天早上在电梯里，邻居跟我打招呼。","py":"Jīntiān zǎoshang zài diàntī lǐ, línjū gēn wǒ dǎ zhāohu.","vi":"Sáng nay trong thang máy, hàng xóm chào tôi.","explain":"打招呼 không mang tân ngữ; người được chào đi với 跟/和/向 đặt trước: 跟我打招呼."},
  {"id":"h2-5-05","std":"hsk2","level":5,"type":"Liên từ","wrong":"哪怕明天下大雪，我们就要按时出发。","segments":["哪怕","明天下大雪，","我们","就要按时出发。"],"bad":3,"correct":"哪怕明天下大雪，我们也要按时出发。","py":"Nǎpà míngtiān xià dà xuě, wǒmen yě yào ànshí chūfā.","vi":"Cho dù mai tuyết rơi dày, chúng ta vẫn phải xuất phát đúng giờ.","explain":"哪怕 (cho dù) đi với 也 ở vế sau, giống 即使…也…."},
  {"id":"h2-5-06","std":"hsk2","level":5,"type":"Kết hợp từ","wrong":"警察正在对这件事进行查。","segments":["警察","正在","对这件事","进行查。"],"bad":3,"correct":"警察正在对这件事进行调查。","py":"Jǐngchá zhèngzài duì zhè jiàn shì jìnxíng diàochá.","vi":"Cảnh sát đang tiến hành điều tra việc này.","explain":"进行 chỉ đi với động từ hai âm tiết mang tính trang trọng: 进行调查, 进行讨论. Không nói 进行查."},
  {"id":"h2-5-08","std":"hsk2","level":5,"type":"Bổ ngữ","wrong":"上课铃响了，老师走进去教室。","segments":["上课铃响了，","老师","走进去","教室。"],"bad":2,"correct":"上课铃响了，老师走进教室。","py":"Shàngkè líng xiǎng le, lǎoshī zǒu jìn jiàoshì.","vi":"Chuông vào lớp reo, thầy giáo bước vào lớp học.","explain":"Tân ngữ chỉ nơi chốn không đặt sau 来/去. Nói 走进教室 hoặc 走进教室去."},
  {"id":"h2-5-09","std":"hsk2","level":5,"type":"Bổ ngữ","wrong":"菜点得太多了，我们不能吃完，打包吧。","segments":["菜点得太多了，","我们","不能吃完，","打包吧。"],"bad":2,"correct":"菜点得太多了，我们吃不完，打包吧。","py":"Cài diǎn de tài duō le, wǒmen chī bu wán, dǎbāo ba.","vi":"Gọi nhiều món quá, chúng ta ăn không hết, gói mang về đi.","explain":"Nói \"không làm nổi, không làm hết được\" dùng bổ ngữ khả năng: 吃不完. 不能吃完 nghe như \"không được phép ăn hết\"."},
  {"id":"h2-5-11","std":"hsk2","level":5,"type":"Dùng sai từ","wrong":"外面很冷，多穿点儿衣服，以便感冒。","segments":["外面很冷，","多穿点儿衣服，","以便","感冒。"],"bad":2,"correct":"外面很冷，多穿点儿衣服，以免感冒。","py":"Wàimiàn hěn lěng, duō chuān diǎnr yīfu, yǐmiǎn gǎnmào.","vi":"Bên ngoài lạnh lắm, mặc thêm áo vào kẻo bị cảm.","explain":"以免 nghĩa là \"để tránh, kẻo\" (đi với điều không mong muốn); 以便 nghĩa là \"để tiện cho\" (đi với mục đích tốt)."},
  {"id":"h2-5-12","std":"hsk2","level":5,"type":"Thiếu/thừa thành phần","wrong":"他病得很重，看来这次非住院。","segments":["他病得很重，","看来","这次","非住院。"],"bad":3,"correct":"他病得很重，看来这次非住院不可。","py":"Tā bìng de hěn zhòng, kànlai zhè cì fēi zhùyuàn bùkě.","vi":"Anh ấy ốm nặng, xem ra lần này buộc phải nằm viện.","explain":"非 với nghĩa \"nhất định phải\" đi thành cấu trúc 非…不可; thiếu 不可 thì câu chưa trọn."},
  {"id":"h2-5-13","std":"hsk2","level":5,"type":"Kết hợp từ","wrong":"政府采取了很多措施来提高城市环境。","segments":["政府","采取了很多措施","来提高","城市环境。"],"bad":2,"correct":"政府采取了很多措施来改善城市环境。","py":"Zhèngfǔ cǎiqǔ le hěn duō cuòshī lái gǎishàn chéngshì huánjìng.","vi":"Chính phủ đã đưa ra nhiều biện pháp để cải thiện môi trường đô thị.","explain":"环境 (môi trường) đi với 改善 (cải thiện) hoặc 保护; 提高 đi với 水平, 质量, 能力."},
  {"id":"h2-5-14","std":"hsk2","level":5,"type":"Dùng sai từ","wrong":"那个国家的经济很发展，人们的生活水平很高。","segments":["那个国家的","经济","很发展，","人们的生活水平很高。"],"bad":2,"correct":"那个国家的经济很发达，人们的生活水平很高。","py":"Nàge guójiā de jīngjì hěn fādá, rénmen de shēnghuó shuǐpíng hěn gāo.","vi":"Kinh tế nước đó rất phát triển, mức sống của người dân rất cao.","explain":"发展 là động từ (phát triển, sự phát triển); muốn nói trạng thái \"đã phát triển\" dùng tính từ 发达: 很发达."},
  {"id":"h2-5-15","std":"hsk2","level":5,"type":"Dùng sai từ","wrong":"经过三年的努力，他终于到达了目的。","segments":["经过三年的努力，","他","终于","到达了目的。"],"bad":3,"correct":"经过三年的努力，他终于达到了目的。","py":"Jīngguò sān nián de nǔlì, tā zhōngyú dádào le mùdì.","vi":"Sau ba năm nỗ lực, cuối cùng anh ấy đã đạt được mục đích.","explain":"达到 (đạt tới) đi với mục tiêu, tiêu chuẩn, mục đích; 到达 (đến nơi) đi với địa điểm."},
  {"id":"h2-5-16","std":"hsk2","level":5,"type":"Thiếu/thừa thành phần","wrong":"经常运动对身体很好处。","segments":["经常","运动","对身体","很好处。"],"bad":3,"correct":"经常运动对身体很有好处。","py":"Jīngcháng yùndòng duì shēntǐ hěn yǒu hǎochu.","vi":"Thường xuyên vận động rất có lợi cho sức khỏe.","explain":"好处 là danh từ, không đứng ngay sau 很. Phải nói 对……有好处; muốn nhấn mạnh thì 很有好处."},
  {"id":"h2-5-17","std":"hsk2","level":5,"type":"Trật tự từ","wrong":"同学之间应该帮助互相，共同进步。","segments":["同学之间","应该","帮助互相，","共同进步。"],"bad":2,"correct":"同学之间应该互相帮助，共同进步。","py":"Tóngxué zhījiān yīnggāi hùxiāng bāngzhù, gòngtóng jìnbù.","vi":"Bạn học với nhau nên giúp đỡ lẫn nhau, cùng nhau tiến bộ.","explain":"互相 là phó từ, đứng trước động từ: 互相帮助. Tiếng Việt nói \"giúp đỡ lẫn nhau\" nên dễ đặt sai."},
  {"id":"h2-5-18","std":"hsk2","level":5,"type":"Trật tự từ","wrong":"这件事交给小李吧，他很有经验在这方面。","segments":["这件事","交给小李吧，","他","很有经验在这方面。"],"bad":3,"correct":"这件事交给小李吧，他在这方面很有经验。","py":"Zhè jiàn shì jiāo gěi Xiǎo Lǐ ba, tā zài zhè fāngmiàn hěn yǒu jīngyàn.","vi":"Việc này giao cho Tiểu Lý đi, anh ấy rất có kinh nghiệm về mặt này.","explain":"Trạng ngữ chỉ phạm vi 在……方面 đứng trước vị ngữ: 在这方面很有经验, không đặt cuối câu như tiếng Việt."},
  {"id":"h2-5-20","std":"hsk2","level":5,"type":"Liên từ","wrong":"听了我的话，他不但没生气，而且笑了。","segments":["听了我的话，","他不但没生气，","而且","笑了。"],"bad":2,"correct":"听了我的话，他不但没生气，反而笑了。","py":"Tīng le wǒ de huà, tā búdàn méi shēngqì, fǎn'ér xiào le.","vi":"Nghe tôi nói, anh ấy không những không giận mà ngược lại còn cười.","explain":"Vế đầu là 不但不/没 và vế sau trái với điều người ta chờ đợi thì phải dùng 反而, không dùng 而且."},
  {"id":"h3-1-01","std":"hsk3","level":1,"type":"Thiếu/thừa thành phần","wrong":"这个苹果是很好吃，你吃一个吧。","segments":["这个","苹果","是很好吃，","你吃一个吧。"],"bad":2,"correct":"这个苹果很好吃，你吃一个吧。","py":"Zhège píngguǒ hěn hǎochī, nǐ chī yí ge ba.","vi":"Quả táo này ngon lắm, bạn ăn một quả đi.","explain":"Tính từ làm vị ngữ không cần 是: 很好吃. Câu \"quả táo là rất ngon\" là lối dịch từng chữ."},
  {"id":"h3-1-02","std":"hsk3","level":1,"type":"Thiếu/thừa thành phần","wrong":"我们学校有十个中国老师们。","segments":["我们学校","有","十个","中国老师们。"],"bad":3,"correct":"我们学校有十个中国老师。","py":"Wǒmen xuéxiào yǒu shí ge Zhōngguó lǎoshī.","vi":"Trường chúng tôi có mười giáo viên Trung Quốc.","explain":"Trước danh từ đã có số lượng (十个) thì không thêm 们 vào sau danh từ chỉ người."},
  {"id":"h3-1-03","std":"hsk3","level":1,"type":"Dùng sai từ","wrong":"这件衣服一点儿贵，有便宜一点儿的吗？","segments":["这件衣服","一点儿贵，","有便宜","一点儿的吗？"],"bad":1,"correct":"这件衣服有点儿贵，有便宜一点儿的吗？","py":"Zhè jiàn yīfu yǒudiǎnr guì, yǒu piányi yìdiǎnr de ma?","vi":"Cái áo này hơi đắt, có cái nào rẻ hơn một chút không?","explain":"\"Hơi đắt\" là 有点儿 + tính từ, đứng trước tính từ. 一点儿 đứng sau tính từ khi so sánh, như 便宜一点儿."},
  {"id":"h3-1-04","std":"hsk3","level":1,"type":"不/没","wrong":"今天是星期天，他不有课。","segments":["今天","是星期天，","他","不有课。"],"bad":3,"correct":"今天是星期天，他没有课。","py":"Jīntiān shì xīngqītiān, tā méiyǒu kè.","vi":"Hôm nay là chủ nhật, anh ấy không có tiết học.","explain":"Động từ 有 chỉ phủ định bằng 没: 没有课, không nói 不有."},
  {"id":"h3-1-05","std":"hsk3","level":1,"type":"不/没","wrong":"昨天他生病了，不来学校。","segments":["昨天","他生病了，","不来","学校。"],"bad":2,"correct":"昨天他生病了，没来学校。","py":"Zuótiān tā shēngbìng le, méi lái xuéxiào.","vi":"Hôm qua cậu ấy ốm nên không đến trường.","explain":"Nói việc đã không xảy ra (hôm qua không đến) dùng 没. 不 dùng cho thói quen, ý muốn hoặc tương lai."},
  {"id":"h3-1-06","std":"hsk3","level":1,"type":"Trật tự từ","wrong":"中午我们去饭店中国吃饭吧。","segments":["中午","我们","去饭店中国","吃饭吧。"],"bad":2,"correct":"中午我们去中国饭店吃饭吧。","py":"Zhōngwǔ wǒmen qù Zhōngguó fàndiàn chīfàn ba.","vi":"Trưa nay chúng ta đi nhà hàng Trung Quốc ăn cơm nhé.","explain":"Từ bổ nghĩa đứng trước danh từ: 中国饭店 (nhà hàng Trung Quốc), ngược với tiếng Việt."},
  {"id":"h3-1-07","std":"hsk3","level":1,"type":"Trật tự từ","wrong":"这不是衣服的我，是我姐姐的。","segments":["这","不是","衣服的我，","是我姐姐的。"],"bad":2,"correct":"这不是我的衣服，是我姐姐的。","py":"Zhè bú shì wǒ de yīfu, shì wǒ jiějie de.","vi":"Đây không phải quần áo của tôi, là của chị tôi.","explain":"Người sở hữu đứng trước, vật đứng sau: 我的衣服."},
  {"id":"h3-1-08","std":"hsk3","level":1,"type":"Trật tự từ","wrong":"妈妈做的菜好吃很。","segments":["妈妈","做的","菜","好吃很。"],"bad":3,"correct":"妈妈做的菜很好吃。","py":"Māma zuò de cài hěn hǎochī.","vi":"Món mẹ nấu rất ngon.","explain":"很 đứng trước tính từ: 很好吃. Không đặt 很 ở cuối câu như \"ngon lắm\"."},
  {"id":"h3-1-09","std":"hsk3","level":1,"type":"Trật tự từ","wrong":"中午我吃饭在学校，不回家。","segments":["中午","我","吃饭在学校，","不回家。"],"bad":2,"correct":"中午我在学校吃饭，不回家。","py":"Zhōngwǔ wǒ zài xuéxiào chīfàn, bù huí jiā.","vi":"Buổi trưa tôi ăn cơm ở trường, không về nhà.","explain":"在 + nơi chốn đứng trước động từ: 在学校吃饭."},
  {"id":"h3-1-10","std":"hsk3","level":1,"type":"Lượng từ","wrong":"我在商店买了两苹果。","segments":["我","在商店","买了","两苹果。"],"bad":3,"correct":"我在商店买了两个苹果。","py":"Wǒ zài shāngdiàn mǎi le liǎng ge píngguǒ.","vi":"Tôi mua hai quả táo ở cửa hàng.","explain":"Số từ không đứng thẳng trước danh từ, giữa chúng phải có lượng từ: 两个苹果."},
  {"id":"h3-1-11","std":"hsk3","level":1,"type":"二/两","wrong":"我有二个姐姐，没有哥哥。","segments":["我","有","二个姐姐，","没有哥哥。"],"bad":2,"correct":"我有两个姐姐，没有哥哥。","py":"Wǒ yǒu liǎng ge jiějie, méiyǒu gēge.","vi":"Tôi có hai chị gái, không có anh trai.","explain":"Trước lượng từ dùng 两: 两个姐姐. 二 dùng khi đếm, đọc số hoặc chỉ thứ tự (第二)."},
  {"id":"h3-1-12","std":"hsk3","level":1,"type":"Câu hỏi","wrong":"你好，请问你叫什么名字吗？","segments":["你好，","请问","你叫","什么名字吗？"],"bad":3,"correct":"你好，请问你叫什么名字？","py":"Nǐ hǎo, qǐngwèn nǐ jiào shénme míngzi?","vi":"Chào bạn, xin hỏi bạn tên là gì?","explain":"Câu hỏi đã có 什么 thì cuối câu không thêm 吗."},
  {"id":"h3-1-13","std":"hsk3","level":1,"type":"Câu hỏi","wrong":"你看，那个人是谁吗？","segments":["你看，","那个人","是","谁吗？"],"bad":3,"correct":"你看，那个人是谁？","py":"Nǐ kàn, nàge rén shì shéi?","vi":"Bạn nhìn kìa, người kia là ai thế?","explain":"谁 đã là từ để hỏi nên không thêm 吗 ở cuối câu."},
  {"id":"h3-1-14","std":"hsk3","level":1,"type":"了/过/着","wrong":"昨天我没看了电视。","segments":["昨天","我","没看了","电视。"],"bad":2,"correct":"昨天我没看电视。","py":"Zuótiān wǒ méi kàn diànshì.","vi":"Hôm qua tôi không xem tivi.","explain":"Câu phủ định với 没 không dùng 了 sau động từ: 没看电视."},
  {"id":"h3-1-15","std":"hsk3","level":1,"type":"不/没","wrong":"今天上午我在学校不看见你。","segments":["今天上午","我","在学校","不看见你。"],"bad":3,"correct":"今天上午我在学校没看见你。","py":"Jīntiān shàngwǔ wǒ zài xuéxiào méi kànjiàn nǐ.","vi":"Sáng nay ở trường tôi không thấy bạn.","explain":"看见 là kết quả của hành động; phủ định một kết quả đã không xảy ra dùng 没: 没看见."},
  {"id":"h3-1-16","std":"hsk3","level":1,"type":"Liên từ","wrong":"我会说汉语，和我也会写汉字。","segments":["我会说汉语，","和我","也会写","汉字。"],"bad":1,"correct":"我会说汉语，我也会写汉字。","py":"Wǒ huì shuō Hànyǔ, wǒ yě huì xiě Hànzì.","vi":"Tôi biết nói tiếng Trung, cũng biết viết chữ Hán.","explain":"和 chỉ nối danh từ, đại từ; không dùng để nối hai vế câu như chữ \"và\"."},
  {"id":"h3-1-17","std":"hsk3","level":1,"type":"的/地/得","wrong":"他有一个很漂亮女朋友。","segments":["他","有","一个","很漂亮女朋友。"],"bad":3,"correct":"他有一个很漂亮的女朋友。","py":"Tā yǒu yí ge hěn piàoliang de nǚpéngyou.","vi":"Anh ấy có một cô bạn gái rất xinh.","explain":"Cụm \"很 + tính từ\" đứng trước danh từ thì phải có 的: 很漂亮的女朋友."},
  {"id":"h3-1-18","std":"hsk3","level":1,"type":"Trật tự từ","wrong":"明天我八点上午上课。","segments":["明天","我","八点上午","上课。"],"bad":2,"correct":"明天我上午八点上课。","py":"Míngtiān wǒ shàngwǔ bā diǎn shàngkè.","vi":"Ngày mai tôi vào học lúc 8 giờ sáng.","explain":"Thời gian nói từ lớn đến nhỏ: 上午八点, không nói 八点上午 như \"8 giờ sáng\"."},
  {"id":"h3-1-19","std":"hsk3","level":1,"type":"Trật tự từ","wrong":"今天是五号九月，星期天。","segments":["今天","是","五号九月，","星期天。"],"bad":2,"correct":"今天是九月五号，星期天。","py":"Jīntiān shì jiǔ yuè wǔ hào, xīngqītiān.","vi":"Hôm nay là ngày 5 tháng 9, chủ nhật.","explain":"Ngày tháng nói theo thứ tự tháng trước, ngày sau: 九月五号."},
  {"id":"h3-1-20","std":"hsk3","level":1,"type":"Trật tự từ","wrong":"妈妈，我想你很，你什么时候来？","segments":["妈妈，","我","想你很，","你什么时候来？"],"bad":2,"correct":"妈妈，我很想你，你什么时候来？","py":"Māma, wǒ hěn xiǎng nǐ, nǐ shénme shíhou lái?","vi":"Mẹ ơi, con nhớ mẹ lắm, khi nào mẹ đến?","explain":"很 đứng trước động từ chỉ tâm lý: 很想你. Tiếng Việt nói \"nhớ lắm\" nên dễ đặt 很 ra sau."},
  {"id":"h3-2-01","std":"hsk3","level":2,"type":"了/过/着","wrong":"快点儿，火车快要开，我们走吧。","segments":["快点儿，","火车","快要开，","我们走吧。"],"bad":2,"correct":"快点儿，火车快要开了，我们走吧。","py":"Kuài diǎnr, huǒchē kuàiyào kāi le, wǒmen zǒu ba.","vi":"Nhanh lên, tàu sắp chạy rồi, chúng ta đi thôi.","explain":"快要 (sắp) luôn đi với 了 ở cuối: 快要开了."},
  {"id":"h3-2-02","std":"hsk3","level":2,"type":"Dùng sai từ","wrong":"我朋友下个月快要回国了。","segments":["我朋友","下个月","快要","回国了。"],"bad":2,"correct":"我朋友下个月就要回国了。","py":"Wǒ péngyou xià ge yuè jiù yào huíguó le.","vi":"Tháng sau bạn tôi về nước rồi.","explain":"Khi trước đó có thời gian cụ thể (下个月, 明天), dùng 就要…了, không dùng 快要…了."},
  {"id":"h3-2-03","std":"hsk3","level":2,"type":"Bổ ngữ","wrong":"老师进来房间了，你没看见吗？","segments":["老师","进来房间了，","你","没看见吗？"],"bad":1,"correct":"老师进房间来了，你没看见吗？","py":"Lǎoshī jìn fángjiān lai le, nǐ méi kànjiàn ma?","vi":"Thầy giáo vào phòng rồi, bạn không thấy à?","explain":"Tân ngữ chỉ nơi chốn phải đứng trước 来/去: 进房间来."},
  {"id":"h3-2-04","std":"hsk3","level":2,"type":"Thiếu/thừa thành phần","wrong":"今天怎么这么很热，我们别出去了。","segments":["今天","怎么","这么很热，","我们别出去了。"],"bad":2,"correct":"今天怎么这么热，我们别出去了。","py":"Jīntiān zěnme zhème rè, wǒmen bié chūqù le.","vi":"Hôm nay sao nóng thế, chúng ta đừng ra ngoài nữa.","explain":"这么/那么 đã chỉ mức độ nên không dùng thêm 很."},
  {"id":"h3-2-05","std":"hsk3","level":2,"type":"Câu so sánh","wrong":"这个房间比那个很大，也很便宜。","segments":["这个房间","比那个","很大，","也很便宜。"],"bad":2,"correct":"这个房间比那个大，也很便宜。","py":"Zhège fángjiān bǐ nàge dà, yě hěn piányi.","vi":"Phòng này rộng hơn phòng kia, lại còn rẻ.","explain":"Câu so sánh với 比 không dùng 很 trước tính từ: 比那个大. Muốn nhấn mạnh thì dùng 大多了 hoặc 更大."},
  {"id":"h3-2-06","std":"hsk3","level":2,"type":"Bổ ngữ","wrong":"我妹妹很喜欢唱歌，她唱很好听。","segments":["我妹妹","很喜欢唱歌，","她","唱很好听。"],"bad":3,"correct":"我妹妹很喜欢唱歌，她唱得很好听。","py":"Wǒ mèimei hěn xǐhuan chànggē, tā chàng de hěn hǎotīng.","vi":"Em gái tôi rất thích hát, em ấy hát rất hay.","explain":"Nhận xét về cách làm một việc phải dùng 得: 唱得很好听."},
  {"id":"h3-2-07","std":"hsk3","level":2,"type":"了/过/着","wrong":"我在中国吃饺子过，很好吃。","segments":["我","在中国","吃饺子过，","很好吃。"],"bad":2,"correct":"我在中国吃过饺子，很好吃。","py":"Wǒ zài Zhōngguó chīguo jiǎozi, hěn hǎochī.","vi":"Tôi từng ăn sủi cảo ở Trung Quốc, ngon lắm.","explain":"过 đứng ngay sau động từ, trước tân ngữ: 吃过饺子."},
  {"id":"h3-2-08","std":"hsk3","level":2,"type":"Giới từ","wrong":"学校从我家很近，我每天走路去。","segments":["学校","从我家","很近，","我每天走路去。"],"bad":1,"correct":"学校离我家很近，我每天走路去。","py":"Xuéxiào lí wǒ jiā hěn jìn, wǒ měi tiān zǒulù qù.","vi":"Trường cách nhà tôi rất gần, ngày nào tôi cũng đi bộ đến.","explain":"Nói khoảng cách giữa hai nơi dùng A 离 B 近/远, không dùng 从."},
  {"id":"h3-2-09","std":"hsk3","level":2,"type":"了/过/着","wrong":"谢谢你，我已经吃饭，现在不想吃。","segments":["谢谢你，","我","已经吃饭，","现在不想吃。"],"bad":2,"correct":"谢谢你，我已经吃饭了，现在不想吃。","py":"Xièxie nǐ, wǒ yǐjīng chīfàn le, xiànzài bù xiǎng chī.","vi":"Cảm ơn bạn, tôi ăn cơm rồi, giờ không muốn ăn nữa.","explain":"已经 đi với 了 để khẳng định việc đã xong: 已经吃饭了."},
  {"id":"h3-2-10","std":"hsk3","level":2,"type":"了/过/着","wrong":"妈妈正在洗了衣服，你等一下。","segments":["妈妈","正在洗了","衣服，","你等一下。"],"bad":1,"correct":"妈妈正在洗衣服，你等一下。","py":"Māma zhèngzài xǐ yīfu, nǐ děng yíxià.","vi":"Mẹ đang giặt quần áo, bạn đợi một chút.","explain":"正在 chỉ hành động đang diễn ra nên không dùng chung với 了 hoàn thành."},
  {"id":"h3-2-11","std":"hsk3","level":2,"type":"Kết hợp từ","wrong":"下课后，我们一起去踢篮球吧。","segments":["下课后，","我们","一起去","踢篮球吧。"],"bad":3,"correct":"下课后，我们一起去打篮球吧。","py":"Xiàkè hòu, wǒmen yìqǐ qù dǎ lánqiú ba.","vi":"Tan học chúng ta cùng đi chơi bóng rổ nhé.","explain":"Bóng rổ chơi bằng tay nên dùng 打篮球; 踢 (đá) dùng cho 足球."},
  {"id":"h3-2-12","std":"hsk3","level":2,"type":"Thiếu/thừa thành phần","wrong":"昨天看的电影很意思，你也去看看吧。","segments":["昨天","看的电影","很意思，","你也去看看吧。"],"bad":2,"correct":"昨天看的电影很有意思，你也去看看吧。","py":"Zuótiān kàn de diànyǐng hěn yǒu yìsi, nǐ yě qù kànkan ba.","vi":"Bộ phim xem hôm qua rất hay, bạn cũng đi xem thử đi.","explain":"意思 là danh từ; \"hay, thú vị\" là 有意思, nên phải nói 很有意思."},
  {"id":"h3-2-13","std":"hsk3","level":2,"type":"Dùng sai từ","wrong":"我和小王是同学，我们知道很多年了。","segments":["我和小王","是同学，","我们","知道很多年了。"],"bad":3,"correct":"我和小王是同学，我们认识很多年了。","py":"Wǒ hé Xiǎo Wáng shì tóngxué, wǒmen rènshi hěn duō nián le.","vi":"Tôi và Tiểu Vương là bạn học, chúng tôi quen nhau nhiều năm rồi.","explain":"Quen biết một người dùng 认识; 知道 là biết một thông tin, sự việc."},
  {"id":"h3-2-14","std":"hsk3","level":2,"type":"Động từ ly hợp","wrong":"这些东西太多了，请你帮忙我拿一下。","segments":["这些东西","太多了，","请你","帮忙我拿一下。"],"bad":3,"correct":"这些东西太多了，请你帮我拿一下。","py":"Zhèxiē dōngxi tài duō le, qǐng nǐ bāng wǒ ná yíxià.","vi":"Đồ nhiều quá, nhờ bạn cầm giúp tôi một chút.","explain":"帮忙 không mang tân ngữ. Muốn nói giúp ai làm gì thì dùng 帮 + người + động từ: 帮我拿一下."},
  {"id":"h3-2-15","std":"hsk3","level":2,"type":"Trật tự từ","wrong":"星期天我一起和朋友去看电影。","segments":["星期天","我","一起和朋友","去看电影。"],"bad":2,"correct":"星期天我和朋友一起去看电影。","py":"Xīngqītiān wǒ hé péngyou yìqǐ qù kàn diànyǐng.","vi":"Chủ nhật tôi cùng bạn đi xem phim.","explain":"Thứ tự đúng là 和 + người + 一起 + động từ, không đặt 一起 trước 和."},
  {"id":"h3-2-16","std":"hsk3","level":2,"type":"的/地/得","wrong":"我的同学说汉语说的很好。","segments":["我的同学","说汉语","说的","很好。"],"bad":2,"correct":"我的同学说汉语说得很好。","py":"Wǒ de tóngxué shuō Hànyǔ shuō de hěn hǎo.","vi":"Bạn cùng lớp của tôi nói tiếng Trung rất giỏi.","explain":"Giữa động từ và bổ ngữ chỉ mức độ dùng 得: 说得很好. 的 đứng trước danh từ."},
  {"id":"h3-2-17","std":"hsk3","level":2,"type":"Trật tự từ","wrong":"大家好，我来从越南，是新同学。","segments":["大家好，","我来从越南，","是","新同学。"],"bad":1,"correct":"大家好，我从越南来，是新同学。","py":"Dàjiā hǎo, wǒ cóng Yuènán lái, shì xīn tóngxué.","vi":"Chào mọi người, mình đến từ Việt Nam, là bạn học mới.","explain":"Cụm 从 + nơi chốn đứng trước động từ: 从越南来. Tiếng Việt nói \"đến từ Việt Nam\" nên dễ đặt 从 ra sau."},
  {"id":"h3-2-18","std":"hsk3","level":2,"type":"二/两","wrong":"我去过二次北京，很喜欢那里。","segments":["我","去过","二次北京，","很喜欢那里。"],"bad":2,"correct":"我去过两次北京，很喜欢那里。","py":"Wǒ qùguo liǎng cì Běijīng, hěn xǐhuan nàli.","vi":"Tôi đã đến Bắc Kinh hai lần, rất thích nơi đó.","explain":"Trước lượng từ (kể cả lượng từ chỉ số lần như 次) dùng 两: 两次."},
  {"id":"h3-2-19","std":"hsk3","level":2,"type":"Bổ ngữ","wrong":"妈妈，我做饭完了，你们来吃吧。","segments":["妈妈，","我","做饭完了，","你们来吃吧。"],"bad":2,"correct":"妈妈，我做完饭了，你们来吃吧。","py":"Māma, wǒ zuò wán fàn le, nǐmen lái chī ba.","vi":"Mẹ ơi, con nấu cơm xong rồi, cả nhà vào ăn đi.","explain":"Bổ ngữ kết quả 完 đứng liền sau động từ, trước tân ngữ: 做完饭."},
  {"id":"h3-2-20","std":"hsk3","level":2,"type":"Liên từ","wrong":"因为路很远，但是我们坐车去吧。","segments":["因为","路很远，","但是我们","坐车去吧。"],"bad":2,"correct":"因为路很远，所以我们坐车去吧。","py":"Yīnwèi lù hěn yuǎn, suǒyǐ wǒmen zuò chē qù ba.","vi":"Vì đường xa nên chúng ta đi xe nhé.","explain":"因为 đi với 所以 để nối nguyên nhân và kết quả; 但是 dùng cho hai vế trái ý."},
  {"id":"h3-3-01","std":"hsk3","level":3,"type":"Thiếu/thừa thành phần","wrong":"来中国以后，他的汉语越来越很好，真不错。","segments":["来中国以后，","他的汉语","越来越很好，","真不错。"],"bad":2,"correct":"来中国以后，他的汉语越来越好，真不错。","py":"Lái Zhōngguó yǐhòu, tā de Hànyǔ yuèláiyuè hǎo, zhēn búcuò.","vi":"Từ khi sang Trung Quốc, tiếng Trung của cậu ấy ngày càng giỏi, đáng khen thật.","explain":"越来越 đã diễn tả mức độ tăng dần, tính từ phía sau không thêm 很."},
  {"id":"h3-3-02","std":"hsk3","level":3,"type":"就/才","wrong":"昨天晚上他直到十二点就睡觉。","segments":["昨天晚上","他直到十二点","就","睡觉。"],"bad":2,"correct":"昨天晚上他直到十二点才睡觉。","py":"Zuótiān wǎnshang tā zhídào shí'èr diǎn cái shuìjiào.","vi":"Tối qua mãi đến 12 giờ anh ấy mới đi ngủ.","explain":"直到 (mãi đến) nhấn mạnh việc xảy ra muộn nên đi với 才. 就 mang ý sớm, nhanh."},
  {"id":"h3-3-03","std":"hsk3","level":3,"type":"就/才","wrong":"我一下课才去找你。","segments":["我","一下课","才去","找你。"],"bad":2,"correct":"我一下课就去找你。","py":"Wǒ yí xiàkè jiù qù zhǎo nǐ.","vi":"Tôi vừa tan học là đi tìm bạn ngay.","explain":"Cấu trúc 一…就… (vừa … là …) dùng 就, không dùng 才."},
  {"id":"h3-3-04","std":"hsk3","level":3,"type":"Kết hợp từ","wrong":"除了游泳以外，他都喜欢跑步。","segments":["除了游泳以外，","他","都喜欢","跑步。"],"bad":2,"correct":"除了游泳以外，他还喜欢跑步。","py":"Chúle yóuyǒng yǐwài, tā hái xǐhuan pǎobù.","vi":"Ngoài bơi lội, anh ấy còn thích chạy bộ.","explain":"Nghĩa \"ngoài … ra còn\" dùng 除了…以外，还/也…; 都 chỉ dùng khi nghĩa là \"trừ … ra thì tất cả đều\"."},
  {"id":"h3-3-05","std":"hsk3","level":3,"type":"Kết hợp từ","wrong":"我对历史很兴趣，常常看历史书。","segments":["我","对历史","很兴趣，","常常看历史书。"],"bad":2,"correct":"我对历史很感兴趣，常常看历史书。","py":"Wǒ duì lìshǐ hěn gǎn xìngqù, chángcháng kàn lìshǐ shū.","vi":"Tôi rất hứng thú với lịch sử, thường đọc sách lịch sử.","explain":"兴趣 là danh từ, phải dùng 对……感兴趣 hoặc 有兴趣, không nói 很兴趣."},
  {"id":"h3-3-06","std":"hsk3","level":3,"type":"Câu chữ 把/被","wrong":"房间里太热了，请把门开。","segments":["房间里","太热了，","请","把门开。"],"bad":3,"correct":"房间里太热了，请把门打开。","py":"Fángjiān lǐ tài rè le, qǐng bǎ mén dǎkāi.","vi":"Trong phòng nóng quá, làm ơn mở cửa ra.","explain":"Động từ trong câu chữ 把 phải có thành phần đi kèm cho biết kết quả: 把门打开."},
  {"id":"h3-3-07","std":"hsk3","level":3,"type":"Bổ ngữ","wrong":"他的汉字写很漂亮，我很喜欢。","segments":["他的汉字","写很漂亮，","我","很喜欢。"],"bad":1,"correct":"他的汉字写得很漂亮，我很喜欢。","py":"Tā de Hànzì xiě de hěn piàoliang, wǒ hěn xǐhuan.","vi":"Chữ Hán cậu ấy viết rất đẹp, tôi rất thích.","explain":"Đánh giá kết quả, cách làm một việc dùng bổ ngữ trạng thái: 写得很漂亮."},
  {"id":"h3-3-08","std":"hsk3","level":3,"type":"Bổ ngữ","wrong":"爬了三个小时的山，我不走动了，休息一下吧。","segments":["爬了三个小时的山，","我","不走动了，","休息一下吧。"],"bad":2,"correct":"爬了三个小时的山，我走不动了，休息一下吧。","py":"Pá le sān ge xiǎoshí de shān, wǒ zǒu bu dòng le, xiūxi yíxià ba.","vi":"Leo núi ba tiếng rồi, tôi đi không nổi nữa, nghỉ một lát đi.","explain":"Bổ ngữ khả năng đặt 不 giữa động từ và bổ ngữ: 走不动 (đi không nổi)."},
  {"id":"h3-3-09","std":"hsk3","level":3,"type":"Dùng sai từ","wrong":"几年不见，他变成很胖，我都快不认识他了。","segments":["几年不见，","他","变成很胖，","我都快不认识他了。"],"bad":2,"correct":"几年不见，他变得很胖，我都快不认识他了。","py":"Jǐ nián bú jiàn, tā biàn de hěn pàng, wǒ dōu kuài bú rènshi tā le.","vi":"Mấy năm không gặp, anh ấy béo ra nhiều, tôi suýt không nhận ra.","explain":"变成 + danh từ (biến thành cái gì); trước tính từ dùng 变得: 变得很胖."},
  {"id":"h3-3-10","std":"hsk3","level":3,"type":"Dùng sai từ","wrong":"我刚才来中国一个月，汉语还不太好。","segments":["我","刚才","来中国","一个月，汉语还不太好。"],"bad":1,"correct":"我刚来中国一个月，汉语还不太好。","py":"Wǒ gāng lái Zhōngguó yí ge yuè, Hànyǔ hái bú tài hǎo.","vi":"Tôi mới sang Trung Quốc được một tháng, tiếng Trung còn chưa giỏi.","explain":"刚 (mới vừa) là phó từ, có thể đi với một khoảng thời gian; 刚才 (lúc nãy) chỉ thời điểm cách đây vài phút."},
  {"id":"h3-3-11","std":"hsk3","level":3,"type":"Kết hợp từ","wrong":"这家饭店的菜很好吃，很被欢迎，每天人都很多。","segments":["这家饭店","的菜很好吃，","很被欢迎，","每天人都很多。"],"bad":2,"correct":"这家饭店的菜很好吃，很受欢迎，每天人都很多。","py":"Zhè jiā fàndiàn de cài hěn hǎochī, hěn shòu huānyíng, měi tiān rén dōu hěn duō.","vi":"Nhà hàng này nấu ngon, rất được ưa chuộng, ngày nào cũng đông khách.","explain":"\"Được ưa chuộng\" là 受欢迎. 被 dùng cho câu bị động có hành động cụ thể, không đi với 欢迎 theo cách này."},
  {"id":"h3-3-12","std":"hsk3","level":3,"type":"Liên từ","wrong":"只有多听多说，就能学好汉语。","segments":["只有","多听多说，","就能","学好汉语。"],"bad":2,"correct":"只有多听多说，才能学好汉语。","py":"Zhǐyǒu duō tīng duō shuō, cái néng xué hǎo Hànyǔ.","vi":"Chỉ có nghe nhiều nói nhiều mới học giỏi được tiếng Trung.","explain":"只有 (chỉ có) nêu điều kiện duy nhất, đi với 才; 只要 mới đi với 就."},
  {"id":"h3-3-13","std":"hsk3","level":3,"type":"Dùng sai từ","wrong":"你想喝茶或者喝咖啡？","segments":["你","想喝茶","或者","喝咖啡？"],"bad":2,"correct":"你想喝茶还是喝咖啡？","py":"Nǐ xiǎng hē chá háishi hē kāfēi?","vi":"Bạn muốn uống trà hay cà phê?","explain":"Câu hỏi lựa chọn dùng 还是; 或者 dùng trong câu kể (喝茶或者喝咖啡都可以)."},
  {"id":"h3-3-14","std":"hsk3","level":3,"type":"Lượng từ","wrong":"今天上午我有三个课，下午没有。","segments":["今天上午","我","有三个课，","下午没有。"],"bad":2,"correct":"今天上午我有三节课，下午没有。","py":"Jīntiān shàngwǔ wǒ yǒu sān jié kè, xiàwǔ méiyǒu.","vi":"Sáng nay tôi có ba tiết học, buổi chiều thì không.","explain":"Tiết học dùng lượng từ 节: 三节课."},
  {"id":"h3-3-15","std":"hsk3","level":3,"type":"Thiếu/thừa thành phần","wrong":"我上大学时候，常常去图书馆。","segments":["我","上大学时候，","常常","去图书馆。"],"bad":1,"correct":"我上大学的时候，常常去图书馆。","py":"Wǒ shàng dàxué de shíhou, chángcháng qù túshūguǎn.","vi":"Hồi học đại học, tôi thường đến thư viện.","explain":"\"Khi…\" là …的时候; phía trước là cụm động từ thì phải có 的: 上大学的时候."},
  {"id":"h3-3-16","std":"hsk3","level":3,"type":"Câu so sánh","wrong":"这个房间跟那个房间一样很大，你住哪个都行。","segments":["这个房间","跟那个房间","一样很大，","你住哪个都行。"],"bad":2,"correct":"这个房间跟那个房间一样大，你住哪个都行。","py":"Zhège fángjiān gēn nàge fángjiān yíyàng dà, nǐ zhù nǎge dōu xíng.","vi":"Phòng này rộng bằng phòng kia, bạn ở phòng nào cũng được.","explain":"Trong câu A 跟 B 一样 + tính từ, không thêm 很 trước tính từ."},
  {"id":"h3-3-17","std":"hsk3","level":3,"type":"Trật tự từ","wrong":"明天下午我们见面在学校门口吧，别忘了。","segments":["明天下午","我们","见面在学校门口吧，","别忘了。"],"bad":2,"correct":"明天下午我们在学校门口见面吧，别忘了。","py":"Míngtiān xiàwǔ wǒmen zài xuéxiào ménkǒu jiànmiàn ba, bié wàng le.","vi":"Chiều mai chúng ta gặp nhau ở cổng trường nhé, đừng quên đấy.","explain":"Cụm 在 + nơi chốn đứng trước động từ: 在学校门口见面, không đặt sau như tiếng Việt."},
  {"id":"h3-3-18","std":"hsk3","level":3,"type":"了/过/着","wrong":"小时候我经常去了那个公园。","segments":["小时候","我","经常去了","那个公园。"],"bad":2,"correct":"小时候我经常去那个公园。","py":"Xiǎoshíhou wǒ jīngcháng qù nàge gōngyuán.","vi":"Hồi nhỏ tôi thường đến công viên đó.","explain":"Hành động lặp lại thường xuyên (经常, 每天) không dùng 了 hoàn thành sau động từ."},
  {"id":"h3-3-20","std":"hsk3","level":3,"type":"Dùng sai từ","wrong":"妈妈做的这个菜有点儿好吃，我还想吃。","segments":["妈妈做的","这个菜","有点儿好吃，","我还想吃。"],"bad":2,"correct":"妈妈做的这个菜很好吃，我还想吃。","py":"Māma zuò de zhège cài hěn hǎochī, wǒ hái xiǎng chī.","vi":"Món mẹ nấu này ngon lắm, tôi còn muốn ăn nữa.","explain":"有点儿 + tính từ thường diễn tả điều không như ý (hơi đắt, hơi mệt), không dùng với lời khen như 好吃. Ở đây dùng 很好吃."},
  {"id":"h3-4-01","std":"hsk3","level":4,"type":"Liên từ","wrong":"无论天气很冷，他都坚持跑步。","segments":["无论","天气很冷，","他","都坚持跑步。"],"bad":1,"correct":"无论天气多冷，他都坚持跑步。","py":"Wúlùn tiānqì duō lěng, tā dōu jiānchí pǎobù.","vi":"Dù trời lạnh đến đâu, anh ấy vẫn kiên trì chạy bộ.","explain":"Sau 无论/不管 phải là cụm có từ để hỏi (多冷, 怎么样) hoặc có lựa chọn; không dùng câu khẳng định như 天气很冷."},
  {"id":"h3-4-02","std":"hsk3","level":4,"type":"Liên từ","wrong":"即使你不告诉我，我就知道。","segments":["即使","你不告诉我，","我","就知道。"],"bad":3,"correct":"即使你不告诉我，我也知道。","py":"Jíshǐ nǐ bú gàosu wǒ, wǒ yě zhīdào.","vi":"Cho dù bạn không nói, tôi cũng biết.","explain":"即使 (cho dù) đi với 也 ở vế sau, không đi với 就."},
  {"id":"h3-4-03","std":"hsk3","level":4,"type":"Thiếu/thừa thành phần","wrong":"最近工作太忙，他连吃饭的时间没有。","segments":["最近","工作太忙，","他","连吃饭的时间没有。"],"bad":3,"correct":"最近工作太忙，他连吃饭的时间都没有。","py":"Zuìjìn gōngzuò tài máng, tā lián chīfàn de shíjiān dōu méiyǒu.","vi":"Dạo này công việc bận quá, anh ấy đến thời gian ăn cơm cũng không có.","explain":"Cấu trúc 连…都/也… phải có 都 hoặc 也 trước động từ: 连吃饭的时间都没有."},
  {"id":"h3-4-04","std":"hsk3","level":4,"type":"Liên từ","wrong":"尽管他已经很努力了，所以考试还是没通过。","segments":["尽管","他已经很努力了，","所以","考试还是没通过。"],"bad":2,"correct":"尽管他已经很努力了，但是考试还是没通过。","py":"Jǐnguǎn tā yǐjīng hěn nǔlì le, dànshì kǎoshì háishi méi tōngguò.","vi":"Mặc dù anh ấy đã rất cố gắng nhưng vẫn thi trượt.","explain":"尽管 (mặc dù) đi với 但是/可是/还是 ở vế sau; 所以 dùng cho quan hệ nguyên nhân – kết quả."},
  {"id":"h3-4-05","std":"hsk3","level":4,"type":"Trật tự từ","wrong":"我已经学了汉语两年，还想继续学。","segments":["我","已经","学了汉语两年，","还想继续学。"],"bad":2,"correct":"我已经学了两年汉语，还想继续学。","py":"Wǒ yǐjīng xué le liǎng nián Hànyǔ, hái xiǎng jìxù xué.","vi":"Tôi đã học tiếng Trung hai năm, còn muốn học tiếp.","explain":"Khoảng thời gian của hành động đứng sau động từ và trước tân ngữ: 学了两年汉语 (hoặc 汉语学了两年)."},
  {"id":"h3-4-07","std":"hsk3","level":4,"type":"Câu so sánh","wrong":"今年公司的收入高于比去年，大家都很高兴。","segments":["今年","公司的收入","高于比去年，","大家都很高兴。"],"bad":2,"correct":"今年公司的收入高于去年，大家都很高兴。","py":"Jīnnián gōngsī de shōurù gāoyú qùnián, dàjiā dōu hěn gāoxìng.","vi":"Năm nay thu nhập của công ty cao hơn năm ngoái, mọi người đều rất vui.","explain":"高于 đã chứa nghĩa so sánh (于 = so với), nên không thêm 比."},
  {"id":"h3-4-08","std":"hsk3","level":4,"type":"Lượng từ","wrong":"他们俩个是好朋友。","segments":["他们","俩个","是","好朋友。"],"bad":1,"correct":"他们俩是好朋友。","py":"Tāmen liǎ shì hǎo péngyou.","vi":"Hai người họ là bạn thân.","explain":"俩 đã có nghĩa là 两个 nên không thêm 个 phía sau."},
  {"id":"h3-4-09","std":"hsk3","level":4,"type":"Câu chữ 把/被","wrong":"桌子上的蛋糕被弟弟吃。","segments":["桌子上的","蛋糕","被弟弟","吃。"],"bad":3,"correct":"桌子上的蛋糕被弟弟吃了。","py":"Zhuōzi shang de dàngāo bèi dìdi chī le.","vi":"Cái bánh trên bàn bị em trai ăn mất rồi.","explain":"Câu chữ 被 không kết thúc bằng một động từ trơ; sau động từ phải có 了 hoặc bổ ngữ: 吃了, 吃完了."},
  {"id":"h3-4-11","std":"hsk3","level":4,"type":"Trật tự từ","wrong":"我没见他三天了，不知道他去哪儿了。","segments":["我","没见他三天了，","不知道","他去哪儿了。"],"bad":1,"correct":"我三天没见他了，不知道他去哪儿了。","py":"Wǒ sān tiān méi jiàn tā le, bù zhīdào tā qù nǎr le.","vi":"Đã ba ngày tôi không gặp anh ấy, không biết anh ấy đi đâu rồi.","explain":"Trong câu phủ định, khoảng thời gian đứng trước 没: 三天没见他了 (ba ngày rồi không gặp)."},
  {"id":"h3-4-12","std":"hsk3","level":4,"type":"Dùng sai từ","wrong":"我认为今天是星期五，原来是星期六。","segments":["我","认为今天是星期五，","原来","是星期六。"],"bad":1,"correct":"我以为今天是星期五，原来是星期六。","py":"Wǒ yǐwéi jīntiān shì xīngqīwǔ, yuánlái shì xīngqīliù.","vi":"Tôi cứ tưởng hôm nay là thứ Sáu, hóa ra là thứ Bảy.","explain":"以为 là \"cứ tưởng\" (nghĩ vậy nhưng hóa ra sai); 认为 là \"cho rằng\" khi nêu ý kiến, nhận định."},
  {"id":"h3-4-13","std":"hsk3","level":4,"type":"Dùng sai từ","wrong":"那个人前天来过，昨天再来了。","segments":["那个人","前天来过，","昨天","再来了。"],"bad":3,"correct":"那个人前天来过，昨天又来了。","py":"Nàge rén qiántiān láiguo, zuótiān yòu lái le.","vi":"Người đó hôm kia đã đến, hôm qua lại đến nữa.","explain":"Hành động lặp lại đã xảy ra dùng 又; 再 dùng cho lần lặp lại chưa xảy ra."},
  {"id":"h3-4-14","std":"hsk3","level":4,"type":"Liên từ","wrong":"这家饭店不仅菜好吃，但是价格也便宜。","segments":["这家饭店","不仅菜好吃，","但是","价格也便宜。"],"bad":2,"correct":"这家饭店不仅菜好吃，而且价格也便宜。","py":"Zhè jiā fàndiàn bùjǐn cài hǎochī, érqiě jiàgé yě piányi.","vi":"Nhà hàng này không chỉ nấu ngon mà giá còn rẻ.","explain":"不仅 (không chỉ) đi với 而且 (mà còn) để nói ý tăng tiến; 但是 dùng cho ý trái ngược."},
  {"id":"h3-4-15","std":"hsk3","level":4,"type":"Dùng sai từ","wrong":"这件衣服很漂亮，值得三百块。","segments":["这件衣服","很漂亮，","值得","三百块。"],"bad":2,"correct":"这件衣服很漂亮，值三百块。","py":"Zhè jiàn yīfu hěn piàoliang, zhí sānbǎi kuài.","vi":"Cái áo này rất đẹp, đáng giá ba trăm tệ.","explain":"值 + số tiền nghĩa là \"đáng giá bao nhiêu\"; 值得 + động từ nghĩa là \"đáng để làm gì\" (值得买, 值得看)."},
  {"id":"h3-4-16","std":"hsk3","level":4,"type":"Động từ ly hợp","wrong":"他生病了，向公司请假了三天。","segments":["他","生病了，","向公司","请假了三天。"],"bad":3,"correct":"他生病了，向公司请了三天假。","py":"Tā shēngbìng le, xiàng gōngsī qǐng le sān tiān jià.","vi":"Anh ấy bị ốm nên xin công ty nghỉ ba ngày.","explain":"请假 là động từ ly hợp; 了 và khoảng thời gian chen vào giữa: 请了三天假."},
  {"id":"h3-4-17","std":"hsk3","level":4,"type":"Câu hỏi","wrong":"你到底想要什么吗？","segments":["你","到底","想要","什么吗？"],"bad":3,"correct":"你到底想要什么？","py":"Nǐ dàodǐ xiǎngyào shénme?","vi":"Rốt cuộc bạn muốn gì?","explain":"到底 dùng trong câu hỏi có từ để hỏi (什么, 谁, 怎么); câu đã có 什么 thì không thêm 吗."},
  {"id":"h3-4-18","std":"hsk3","level":4,"type":"Động từ ly hợp","wrong":"昨天晚上我和妈妈聊天了一个小时。","segments":["昨天晚上","我和妈妈","聊天了","一个小时。"],"bad":2,"correct":"昨天晚上我和妈妈聊了一个小时。","py":"Zuótiān wǎnshang wǒ hé māma liáo le yí ge xiǎoshí.","vi":"Tối qua tôi nói chuyện với mẹ một tiếng.","explain":"聊天 là động từ ly hợp; khoảng thời gian đặt sau 聊: 聊了一个小时 (hoặc 聊了一个小时的天)."},
  {"id":"h3-4-19","std":"hsk3","level":4,"type":"Trật tự từ","wrong":"我听不懂，请你说稍微慢一点儿，好吗？","segments":["我听不懂，","请你","说稍微慢一点儿，","好吗？"],"bad":2,"correct":"我听不懂，请你稍微说慢一点儿，好吗？","py":"Wǒ tīng bu dǒng, qǐng nǐ shāowēi shuō màn yìdiǎnr, hǎo ma?","vi":"Tôi nghe không hiểu, bạn nói chậm lại một chút được không?","explain":"稍微 là phó từ, đứng trước động từ: 稍微说慢一点儿 (hoặc 说得稍微慢一点儿)."},
  {"id":"h3-4-20","std":"hsk3","level":4,"type":"Bổ ngữ","wrong":"妈妈，我已经把作业做了完。","segments":["妈妈，","我","已经把作业","做了完。"],"bad":3,"correct":"妈妈，我已经把作业做完了。","py":"Māma, wǒ yǐjīng bǎ zuòyè zuò wán le.","vi":"Mẹ ơi, con làm xong bài tập rồi.","explain":"Bổ ngữ kết quả 完 đứng liền sau động từ, 了 đặt sau bổ ngữ: 做完了."},
  {"id":"h3-5-01","std":"hsk3","level":5,"type":"Thiếu/thừa thành phần","wrong":"在工作中，我们要尽量避免不出现同样的问题。","segments":["在工作中，","我们要","尽量避免不","出现同样的问题。"],"bad":2,"correct":"在工作中，我们要尽量避免出现同样的问题。","py":"Zài gōngzuò zhōng, wǒmen yào jǐnliàng bìmiǎn chūxiàn tóngyàng de wèntí.","vi":"Trong công việc, chúng ta phải cố gắng tránh để xảy ra những vấn đề tương tự.","explain":"避免 (tránh) đã mang nghĩa phủ định; thêm 不 thành phủ định hai lần, nghĩa bị đảo ngược."},
  {"id":"h3-5-02","std":"hsk3","level":5,"type":"Kết hợp từ","wrong":"为了增强产品的质量，公司引进了新技术。","segments":["为了","增强产品的质量，","公司","引进了新技术。"],"bad":1,"correct":"为了提高产品的质量，公司引进了新技术。","py":"Wèile tígāo chǎnpǐn de zhìliàng, gōngsī yǐnjìn le xīn jìshù.","vi":"Để nâng cao chất lượng sản phẩm, công ty đã đưa vào công nghệ mới.","explain":"质量 đi với 提高; 增强 đi với 信心, 体质, 意识 (làm mạnh thêm)."},
  {"id":"h3-5-03","std":"hsk3","level":5,"type":"Kết hợp từ","wrong":"经过一年的努力，他的学习成绩有了很大的发展。","segments":["经过一年的努力，","他的学习成绩","有了很大的","发展。"],"bad":3,"correct":"经过一年的努力，他的学习成绩有了很大的提高。","py":"Jīngguò yì nián de nǔlì, tā de xuéxí chéngjì yǒu le hěn dà de tígāo.","vi":"Sau một năm nỗ lực, thành tích học tập của cậu ấy đã tiến bộ rất nhiều.","explain":"成绩 (thành tích) đi với 提高 hoặc 进步; 发展 dùng cho kinh tế, xã hội, sự nghiệp."},
  {"id":"h3-5-05","std":"hsk3","level":5,"type":"Kết hợp từ","wrong":"老板看了以后，对这个计划进行了改。","segments":["老板","看了以后，","对这个计划","进行了改。"],"bad":3,"correct":"老板看了以后，对这个计划进行了修改。","py":"Lǎobǎn kàn le yǐhòu, duì zhège jìhuà jìnxíng le xiūgǎi.","vi":"Sau khi xem, ông chủ đã sửa lại kế hoạch này.","explain":"进行 chỉ đi với động từ hai âm tiết: 进行修改, 进行讨论. Không nói 进行改."},
  {"id":"h3-5-06","std":"hsk3","level":5,"type":"Trật tự từ","wrong":"经过讨论，其他同事都也同意了这个方案。","segments":["经过讨论，","其他同事","都也同意了","这个方案。"],"bad":2,"correct":"经过讨论，其他同事也都同意了这个方案。","py":"Jīngguò tǎolùn, qítā tóngshì yě dōu tóngyì le zhège fāng'àn.","vi":"Sau khi thảo luận, các đồng nghiệp khác cũng đều đồng ý phương án này.","explain":"Khi 也 và 都 cùng xuất hiện, thứ tự là 也都 (cũng đều), không nói 都也."},
  {"id":"h3-5-08","std":"hsk3","level":5,"type":"了/过/着","wrong":"爬完山以后，大家都觉得了很累。","segments":["爬完山以后，","大家都","觉得了","很累。"],"bad":2,"correct":"爬完山以后，大家都觉得很累。","py":"Pá wán shān yǐhòu, dàjiā dōu juéde hěn lèi.","vi":"Leo núi xong, ai cũng thấy rất mệt.","explain":"Động từ chỉ cảm nghĩ như 觉得, 认为, 希望 không mang 了 ngay phía sau."},
  {"id":"h3-5-09","std":"hsk3","level":5,"type":"Câu so sánh","wrong":"今年夏天比去年非常热，空调卖得特别好。","segments":["今年夏天","比去年","非常热，","空调卖得特别好。"],"bad":2,"correct":"今年夏天比去年更热，空调卖得特别好。","py":"Jīnnián xiàtiān bǐ qùnián gèng rè, kōngtiáo mài de tèbié hǎo.","vi":"Mùa hè năm nay nóng hơn năm ngoái, điều hòa bán rất chạy.","explain":"Sau 比 không dùng 很, 非常; muốn nhấn mạnh thì dùng 更 hoặc 还 trước tính từ."},
  {"id":"h3-5-10","std":"hsk3","level":5,"type":"Câu so sánh","wrong":"我的口语不如他很流利，还要多练习。","segments":["我的口语","不如他","很流利，","还要多练习。"],"bad":2,"correct":"我的口语不如他流利，还要多练习。","py":"Wǒ de kǒuyǔ bùrú tā liúlì, hái yào duō liànxí.","vi":"Khẩu ngữ của tôi không lưu loát bằng anh ấy, tôi còn phải luyện nhiều.","explain":"Câu so sánh với 不如 không dùng 很 trước tính từ: A 不如 B + tính từ."},
  {"id":"h3-5-11","std":"hsk3","level":5,"type":"Thiếu/thừa thành phần","wrong":"因为工作认真，他被受到了公司的表扬。","segments":["因为工作认真，","他","被受到了","公司的表扬。"],"bad":2,"correct":"因为工作认真，他受到了公司的表扬。","py":"Yīnwèi gōngzuò rènzhēn, tā shòudào le gōngsī de biǎoyáng.","vi":"Vì làm việc chăm chỉ, anh ấy được công ty khen ngợi.","explain":"受到 đã mang nghĩa bị động (nhận được, bị), không dùng thêm 被."},
  {"id":"h3-5-12","std":"hsk3","level":5,"type":"Kết hợp từ","wrong":"为了吸引更多顾客，商店减少了价格。","segments":["为了","吸引更多顾客，","商店","减少了价格。"],"bad":3,"correct":"为了吸引更多顾客，商店降低了价格。","py":"Wèile xīyǐn gèng duō gùkè, shāngdiàn jiàngdī le jiàgé.","vi":"Để thu hút thêm khách hàng, cửa hàng đã hạ giá.","explain":"价格 (giá cả) đi với 降低/提高; 减少 dùng cho số lượng (减少人数, 减少浪费)."},
  {"id":"h3-5-13","std":"hsk3","level":5,"type":"Kết hợp từ","wrong":"有时间的话，我想交流你一下。","segments":["有时间的话，","我想","交流你","一下。"],"bad":2,"correct":"有时间的话，我想跟你交流一下。","py":"Yǒu shíjiān dehuà, wǒ xiǎng gēn nǐ jiāoliú yíxià.","vi":"Nếu có thời gian, tôi muốn trao đổi với bạn một chút.","explain":"交流 không mang tân ngữ chỉ người; người cùng trao đổi đi với 跟/和 đặt trước: 跟你交流."},
  {"id":"h3-5-14","std":"hsk3","level":5,"type":"Liên từ","wrong":"天气再冷，他就会去跑步。","segments":["天气","再冷，","他","就会去跑步。"],"bad":3,"correct":"天气再冷，他也会去跑步。","py":"Tiānqì zài lěng, tā yě huì qù pǎobù.","vi":"Trời có lạnh đến đâu, anh ấy cũng đi chạy bộ.","explain":"再 + tính từ ở vế trước mang nghĩa \"dù … đến đâu\", vế sau phải dùng 也."},
  {"id":"h3-5-15","std":"hsk3","level":5,"type":"Dùng sai từ","wrong":"我早就说他会迟到，他居然迟到了。","segments":["我早就说","他会迟到，","他","居然迟到了。"],"bad":3,"correct":"我早就说他会迟到，他果然迟到了。","py":"Wǒ zǎo jiù shuō tā huì chídào, tā guǒrán chídào le.","vi":"Tôi đã nói từ trước là anh ấy sẽ đến muộn, quả nhiên anh ấy đến muộn thật.","explain":"果然 là \"quả nhiên\" (đúng như dự đoán); 居然 là \"vậy mà, không ngờ\" (trái với dự đoán)."},
  {"id":"h3-5-16","std":"hsk3","level":5,"type":"Dùng sai từ","wrong":"这个孩子很聪明，反映很快。","segments":["这个孩子","很聪明，","反映","很快。"],"bad":2,"correct":"这个孩子很聪明，反应很快。","py":"Zhège háizi hěn cōngming, fǎnyìng hěn kuài.","vi":"Đứa trẻ này rất thông minh, phản ứng rất nhanh.","explain":"反应 là phản ứng (của người, cơ thể); 反映 là phản ánh (ý kiến, thực tế). Hai từ đồng âm nhưng khác nghĩa."},
  {"id":"h3-5-17","std":"hsk3","level":5,"type":"Liên từ","wrong":"尽管天气怎么样，比赛都要进行。","segments":["尽管","天气怎么样，","比赛","都要进行。"],"bad":0,"correct":"不管天气怎么样，比赛都要进行。","py":"Bùguǎn tiānqì zěnmeyàng, bǐsài dōu yào jìnxíng.","vi":"Dù thời tiết thế nào, trận đấu vẫn sẽ diễn ra.","explain":"尽管 (mặc dù) đi với một sự thật đã biết; trước từ để hỏi như 怎么样 phải dùng 不管/无论."},
  {"id":"h3-5-18","std":"hsk3","level":5,"type":"Động từ ly hợp","wrong":"我忘了他的生日，他生气我了。","segments":["我","忘了他的生日，","他","生气我了。"],"bad":3,"correct":"我忘了他的生日，他生我的气了。","py":"Wǒ wàng le tā de shēngrì, tā shēng wǒ de qì le.","vi":"Tôi quên sinh nhật anh ấy, anh ấy giận tôi rồi.","explain":"生气 là động từ ly hợp, không mang tân ngữ. Nói 生我的气 hoặc 对我生气."},
  {"id":"h3-5-19","std":"hsk3","level":5,"type":"Câu so sánh","wrong":"这次考试，他的成绩比我差多。","segments":["这次考试，","他的成绩","比我","差多。"],"bad":3,"correct":"这次考试，他的成绩比我差多了。","py":"Zhè cì kǎoshì, tā de chéngjì bǐ wǒ chà duō le.","vi":"Kỳ thi lần này, điểm của cậu ấy kém tôi nhiều.","explain":"Muốn nói \"kém/hơn nhiều\" trong câu so sánh, sau tính từ dùng 多了 hoặc 得多: 差多了."},
  {"id":"h3-5-20","std":"hsk3","level":5,"type":"的/地/得","wrong":"为了早点儿完成任务，大家都在认真的工作。","segments":["为了","早点儿完成任务，","大家都在","认真的工作。"],"bad":3,"correct":"为了早点儿完成任务，大家都在认真地工作。","py":"Wèile zǎo diǎnr wánchéng rènwu, dàjiā dōu zài rènzhēn de gōngzuò.","vi":"Để sớm hoàn thành nhiệm vụ, mọi người đều đang chăm chỉ làm việc.","explain":"Từ bổ nghĩa đứng trước động từ dùng 地: 认真地工作. 的 dùng trước danh từ."},
  {"id":"h3-6-01","std":"hsk3","level":6,"type":"Liên từ","wrong":"我之所以迟到，因为路上堵车了。","segments":["我","之所以迟到，","因为","路上堵车了。"],"bad":2,"correct":"我之所以迟到，是因为路上堵车了。","py":"Wǒ zhīsuǒyǐ chídào, shì yīnwèi lùshang dǔchē le.","vi":"Sở dĩ tôi đến muộn là vì đường bị tắc.","explain":"Vế sau của 之所以 phải là 是因为, không thể chỉ dùng 因为."},
  {"id":"h3-6-02","std":"hsk3","level":6,"type":"Thiếu/thừa thành phần","wrong":"为了防止类似的事故不再发生，工厂加强了管理。","segments":["为了","防止类似的事故","不再发生，","工厂加强了管理。"],"bad":2,"correct":"为了防止类似的事故再发生，工厂加强了管理。","py":"Wèile fángzhǐ lèisì de shìgù zài fāshēng, gōngchǎng jiāqiáng le guǎnlǐ.","vi":"Để ngăn sự cố tương tự xảy ra lần nữa, nhà máy đã tăng cường quản lý.","explain":"防止 (ngăn chặn) đã có nghĩa \"không để xảy ra\", nên phía sau không thêm 不."},
  {"id":"h3-6-03","std":"hsk3","level":6,"type":"Liên từ","wrong":"与其在这里等，还是出去找找。","segments":["与其","在这里等，","还是","出去找找。"],"bad":2,"correct":"与其在这里等，不如出去找找。","py":"Yǔqí zài zhèlǐ děng, bùrú chūqù zhǎozhao.","vi":"Thay vì đứng đây chờ, chi bằng ra ngoài tìm thử.","explain":"与其 A, 不如 B (thay vì A, chi bằng B) là cặp cố định; không dùng 还是 ở vế sau."},
  {"id":"h3-6-04","std":"hsk3","level":6,"type":"Kết hợp từ","wrong":"出了问题，公司应该担任全部责任。","segments":["出了问题，","公司","应该","担任全部责任。"],"bad":3,"correct":"出了问题，公司应该承担全部责任。","py":"Chū le wèntí, gōngsī yīnggāi chéngdān quánbù zérèn.","vi":"Xảy ra vấn đề thì công ty phải chịu toàn bộ trách nhiệm.","explain":"责任 đi với 承担 hoặc 负; 担任 đi với chức vụ (担任经理)."},
  {"id":"h3-6-05","std":"hsk3","level":6,"type":"Kết hợp từ","wrong":"他们打算下个月进行婚礼，邀请了很多朋友。","segments":["他们","打算下个月","进行婚礼，","邀请了很多朋友。"],"bad":2,"correct":"他们打算下个月举行婚礼，邀请了很多朋友。","py":"Tāmen dǎsuàn xià ge yuè jǔxíng hūnlǐ, yāoqǐng le hěn duō péngyou.","vi":"Họ định tháng sau tổ chức đám cưới, đã mời rất nhiều bạn bè.","explain":"婚礼, 典礼, 晚会 đi với 举行 hoặc 举办; 进行 chỉ đi với động từ hai âm tiết như 讨论, 调查."},
  {"id":"h3-6-06","std":"hsk3","level":6,"type":"Thiếu/thừa thành phần","wrong":"对我来说而言，健康比什么都重要。","segments":["对我","来说而言，","健康","比什么都重要。"],"bad":1,"correct":"对我来说，健康比什么都重要。","py":"Duì wǒ lái shuō, jiànkāng bǐ shénme dōu zhòngyào.","vi":"Với tôi, sức khỏe quan trọng hơn mọi thứ.","explain":"对…来说 và 对…而言 cùng nghĩa \"đối với…\", chỉ dùng một trong hai, không ghép 来说而言."},
  {"id":"h3-6-07","std":"hsk3","level":6,"type":"Dùng sai từ","wrong":"按照天气预报，明天会下大雨。","segments":["按照","天气预报，","明天","会下大雨。"],"bad":0,"correct":"根据天气预报，明天会下大雨。","py":"Gēnjù tiānqì yùbào, míngtiān huì xià dà yǔ.","vi":"Theo dự báo thời tiết, ngày mai sẽ mưa to.","explain":"根据 (căn cứ vào) dùng khi dựa vào thông tin, số liệu để nói một điều; 按照 (làm theo) dùng khi làm đúng theo quy định, kế hoạch."},
  {"id":"h3-6-08","std":"hsk3","level":6,"type":"Dùng sai từ","wrong":"对现代人来说，手机已经成了生活必须品。","segments":["对现代人来说，","手机","已经成了","生活必须品。"],"bad":3,"correct":"对现代人来说，手机已经成了生活必需品。","py":"Duì xiàndài rén lái shuō, shǒujī yǐjīng chéng le shēnghuó bìxūpǐn.","vi":"Với người hiện đại, điện thoại đã trở thành vật dụng thiết yếu.","explain":"必需 (cần thiết, không thể thiếu) dùng trong 必需品; 必须 là phó từ \"phải\", không ghép với 品."},
  {"id":"h3-6-09","std":"hsk3","level":6,"type":"Thiếu/thừa thành phần","wrong":"今年参加比赛的人数超过了一千人以上。","segments":["今年","参加比赛的人数","超过了","一千人以上。"],"bad":3,"correct":"今年参加比赛的人数超过了一千人。","py":"Jīnnián cānjiā bǐsài de rénshù chāoguò le yìqiān rén.","vi":"Năm nay số người tham gia cuộc thi đã vượt quá một nghìn.","explain":"超过 (vượt quá) và 以上 (trở lên) trùng nghĩa, chỉ dùng một trong hai."},
  {"id":"h3-6-10","std":"hsk3","level":6,"type":"Dùng sai từ","wrong":"第一次做这种工作，避免会出一些错。","segments":["第一次","做这种工作，","避免会","出一些错。"],"bad":2,"correct":"第一次做这种工作，难免会出一些错。","py":"Dì-yī cì zuò zhè zhǒng gōngzuò, nánmiǎn huì chū yìxiē cuò.","vi":"Lần đầu làm loại việc này thì khó tránh khỏi sai sót.","explain":"难免 là \"khó tránh khỏi\" (điều không hay dễ xảy ra); 避免 là \"tránh\" (chủ động ngăn một việc)."},
  {"id":"h3-6-11","std":"hsk3","level":6,"type":"Câu chữ 把/被","wrong":"今天工作太多，我把这些事做不完。","segments":["今天","工作太多，","我","把这些事做不完。"],"bad":3,"correct":"今天工作太多，我做不完这些事。","py":"Jīntiān gōngzuò tài duō, wǒ zuò bu wán zhèxiē shì.","vi":"Hôm nay nhiều việc quá, tôi làm không hết được.","explain":"Câu chữ 把 không dùng với bổ ngữ khả năng (做不完, 看得懂). Phải nói 我做不完这些事."},
  {"id":"h3-6-12","std":"hsk3","level":6,"type":"Trật tự từ","wrong":"这次会议认真通过并讨论了这个方案。","segments":["这次会议","认真","通过并讨论了","这个方案。"],"bad":2,"correct":"这次会议认真讨论并通过了这个方案。","py":"Zhè cì huìyì rènzhēn tǎolùn bìng tōngguò le zhège fāng'àn.","vi":"Cuộc họp lần này đã thảo luận kỹ và thông qua phương án này.","explain":"Các hành động nối bằng 并 phải theo đúng trình tự: thảo luận trước rồi mới thông qua (讨论并通过)."},
  {"id":"h3-6-13","std":"hsk3","level":6,"type":"Thiếu/thừa thành phần","wrong":"在老师的帮助，我顺利地完成了毕业论文。","segments":["在老师的帮助，","我","顺利地完成了","毕业论文。"],"bad":0,"correct":"在老师的帮助下，我顺利地完成了毕业论文。","py":"Zài lǎoshī de bāngzhù xià, wǒ shùnlì de wánchéng le bìyè lùnwén.","vi":"Nhờ sự giúp đỡ của thầy, tôi đã hoàn thành suôn sẻ luận văn tốt nghiệp.","explain":"Cấu trúc 在……下 (dưới sự …, nhờ có …) phải có đủ 下 ở cuối: 在老师的帮助下."},
  {"id":"h3-6-14","std":"hsk3","level":6,"type":"Giới từ","wrong":"王老师十年前毕业从北京大学。","segments":["王老师","十年前","毕业从","北京大学。"],"bad":2,"correct":"王老师十年前毕业于北京大学。","py":"Wáng lǎoshī shí nián qián bìyè yú Běijīng Dàxué.","vi":"Thầy Vương tốt nghiệp Đại học Bắc Kinh mười năm trước.","explain":"\"Tốt nghiệp trường …\" nói 毕业于 + trường (văn viết) hoặc 从 + trường + 毕业. 从 không đứng sau 毕业."},
  {"id":"h3-6-15","std":"hsk3","level":6,"type":"Dùng sai từ","wrong":"污染问题越来越严格，必须马上解决。","segments":["污染问题","越来越","严格，","必须马上解决。"],"bad":2,"correct":"污染问题越来越严重，必须马上解决。","py":"Wūrǎn wèntí yuèláiyuè yánzhòng, bìxū mǎshàng jiějué.","vi":"Vấn đề ô nhiễm ngày càng nghiêm trọng, phải giải quyết ngay.","explain":"严重 là \"nghiêm trọng\" (mức độ xấu); 严格 là \"nghiêm khắc, chặt chẽ\" (yêu cầu, quản lý)."},
  {"id":"h3-6-16","std":"hsk3","level":6,"type":"Dùng sai từ","wrong":"每个公民都有受教育的权力。","segments":["每个","公民","都有受教育的","权力。"],"bad":3,"correct":"每个公民都有受教育的权利。","py":"Měi ge gōngmín dōu yǒu shòu jiàoyù de quánlì.","vi":"Mọi công dân đều có quyền được học tập.","explain":"权利 là quyền lợi ai cũng được hưởng; 权力 là quyền lực (quyền điều hành, ra lệnh)."},
  {"id":"h3-6-17","std":"hsk3","level":6,"type":"Liên từ","wrong":"这孩子很聪明，而且一点儿也不努力。","segments":["这孩子","很聪明，","而且","一点儿也不努力。"],"bad":2,"correct":"这孩子很聪明，可是一点儿也不努力。","py":"Zhè háizi hěn cōngming, kěshì yìdiǎnr yě bù nǔlì.","vi":"Đứa trẻ này rất thông minh nhưng chẳng chịu cố gắng chút nào.","explain":"Hai vế trái ý (thông minh – không chịu cố gắng) phải nối bằng 可是/但是; 而且 dùng khi vế sau bổ sung cùng chiều."},
  {"id":"h3-6-18","std":"hsk3","level":6,"type":"了/过/着","wrong":"到目前为止，这个问题还没有解决了。","segments":["到目前为止，","这个问题","还没有","解决了。"],"bad":3,"correct":"到目前为止，这个问题还没有解决。","py":"Dào mùqián wéizhǐ, zhège wèntí hái méiyǒu jiějué.","vi":"Cho đến nay, vấn đề này vẫn chưa được giải quyết.","explain":"还没有 + động từ (vẫn chưa) là câu phủ định nên động từ phía sau không mang 了."},
  {"id":"h3-6-19","std":"hsk3","level":6,"type":"Trật tự từ","wrong":"其实他没有并生你的气。","segments":["其实","他","没有并","生你的气。"],"bad":2,"correct":"其实他并没有生你的气。","py":"Qíshí tā bìng méiyǒu shēng nǐ de qì.","vi":"Thật ra anh ấy hoàn toàn không giận bạn.","explain":"并 đứng trước từ phủ định 不/没有 để nhấn mạnh \"thật ra không hề\": 并没有."},
  {"id":"h3-6-20","std":"hsk3","level":6,"type":"Giới từ","wrong":"这家公司一直提供顾客优质的服务。","segments":["这家公司","一直","提供顾客","优质的服务。"],"bad":2,"correct":"这家公司一直为顾客提供优质的服务。","py":"Zhè jiā gōngsī yìzhí wèi gùkè tígōng yōuzhì de fúwù.","vi":"Công ty này luôn cung cấp dịch vụ chất lượng cho khách hàng.","explain":"提供 không nhận người làm tân ngữ trực tiếp; người được cung cấp đi với 为/给 đặt trước: 为顾客提供服务."}
];
